/// Typed LSP/DAP bytes stay unavailable until supervised process lifecycle and
/// platform confinement acceptance are recorded against the integrated revision.
/// The journal/parser code is intentionally present behind this release gate.
const TYPED_PROCESS_PROTOCOL_RUNTIME_READY: bool = false;
// LSP/DAP launch shares the guarded supervisor, but remains unavailable until
// the Core approval/lifecycle adapter and OS acceptance matrix are integrated.
const GUARDED_EDITOR_PROCESS_RUNTIME_READY: bool = false;
/// CodeMode stays hidden until its helper package, Guard dispatcher, cgroup
/// resource limits, cancellation and restart reconciliation pass integrated
/// acceptance on the selected native target.
const CODE_MODE_RUNTIME_READY: bool = false;
/// Guarded PTY execution is available: every terminal.v1/run and
/// terminal.v1/start ingress resolves the registered shell profile, binds a
/// per-effect cgroup-v2 containment identity into the durable PREPARE record
/// before dispatch, settles only an observed exit, and leaves an unobserved
/// exit durably UNKNOWN. OS-level filesystem and network confinement come from
/// the probed sandbox backend (bubblewrap + Landlock), which must report
/// ENFORCED for read, write, egress and process tree or the launch is refused.
const GUARDED_PTY_RUNTIME_READY: bool = true;

/// Bounded live managed-Goal owners. Each Goal holds one durable OwnerLog and one
/// exclusive owner lock for the kernel's lifetime: an instance is never evicted,
/// because reopening a Goal that still has an admitted Attempt would record a
/// false UNKNOWN outcome.
const MAX_MANAGED_GOALS: usize = 64;
/// Bounded live direct-Attempt owners for Goal-less subagent dispatch. Terminal
/// Attempts may be evicted (they reopen from durable state with the same phase);
/// an EXECUTING/UNKNOWN Attempt is never evicted, so no false outcome is recorded.
const MAX_DIRECT_ATTEMPTS: usize = 64;
// Root-session artifact projections are bounded independently from the
// retained batch journal. An old Session may accumulate more than one page of
// terminal output receipts; callers must use a later paged API rather than
// making this authenticated RPC allocate an unbounded history snapshot.
const MAX_DIRECT_SESSION_ARTIFACT_BATCHES: usize = 4096;
const MAX_DIRECT_SESSION_ARTIFACT_REFS: usize = 256;
/// Largest client delivery id that still leaves room for a managed sub-command
/// suffix inside the 256-byte durable identifier bound.
const MAX_MANAGED_DELIVERY_ID_BYTES: usize = 200;
/// Bounded plan-ingress collection sizes, mirroring the managed state machine's
/// own limits so an oversized request fails before any durable write is attempted.
const MAX_SPEC_SCOPE_ITEMS: usize = 128;
const MAX_SPEC_CONSTRAINT_ITEMS: usize = 128;
const MAX_SPEC_CRITERIA: usize = 256;
const MAX_SPEC_SOURCE_DIGESTS: usize = 256;
const MAX_SPEC_CAPABILITY_IDS: usize = 64;
const MAX_TASK_DEPENDENCIES: usize = 256;
const MAX_TASK_CRITERIA: usize = 256;
const MAX_TASK_REQUIRED_CAPABILITIES: usize = 64;
const MAX_PLANNED_TASKS: usize = 64;
const MAX_PLAN_TEXT_BYTES: usize = 16 * 1024;
const MAX_PLAN_ITEM_BYTES: usize = 4 * 1024;
const MAX_PENDING_PROPOSALS_PER_GOAL: usize = 64;
const MAX_TOOL_BATCH_CALLS: usize = 32;
const MAX_TOOL_CALL_ARGUMENT_BYTES: usize = 256 * 1024;
const MAX_TOOL_BATCH_ARGUMENT_BYTES: usize = 512 * 1024;
// Worst-case JSON escaping expands each source byte to six bytes. A 128 KiB
// source cap therefore leaves more than 256 KiB for the LSP envelope under its
// 1 MiB operation/frame limit.
const MAX_REPO_DOCUMENT_BYTES: usize = 131_072;
/// Retained source snapshots stay bounded independently from per-request query
/// limits. This is a source-byte admission bound, not a claim about heap bytes.
const MAX_REPO_RETAINED_SOURCE_BYTES: usize = 67_108_864;
const VERIFIER_PROFILE_CONFIG_FILE: &str = "verifier-profiles.v1.json";
const MAX_VERIFIER_PROFILE_CONFIG_BYTES: usize = 256 * 1024;
const MAX_VERIFIER_PROFILES: usize = 32;
const EXECUTION_SELECTOR_CONFIG_FILE: &str = "execution-selectors.v1.json";
const MAX_EXECUTION_SELECTOR_CONFIG_BYTES: usize = 32 * 1024;
const MAX_EXECUTION_SELECTORS: usize = 16;
const CODEMODE_HELPER_MANIFEST_FILE: &str = "codemode-helper.manifest.json";
const MAX_CODEMODE_HELPER_MANIFEST_BYTES: usize = 4 * 1024;
const MAX_VERIFIER_CRITERIA: usize = 256;
const MAX_VERIFIER_OUTPUT_BYTES: usize = 16 * 1024 * 1024;
const MAX_VERIFIER_AGGREGATE_OUTPUT_BYTES: usize = 64 * 1024 * 1024;
const MAX_VERIFIER_CHALLENGE_SETS: usize = 128;
const HOST_WORKER_POOL_ID: &str = "host-default";

