#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
#[serde(rename_all = "camelCase")]
struct CodeModeHelperManifestV1 {
    schema_version: u8,
    status: String,
    helper_selector: String,
    relative_entrypoint: String,
    sha256: Option<String>,
    target: String,
    #[serde(default)]
    reason: Option<String>,
}

fn load_code_mode_helper_package(
    trusted_install_root: &Path,
    trusted_selectors: &BTreeMap<String, PathBuf>,
) -> Result<Option<crate::terminal_process::CodeModeHelperPackageV1>, String> {
    let unavailable = || Ok(None);
    if !trusted_install_root.is_absolute() {
        return Err("CodeMode install root must be absolute".to_owned());
    }
    let root_link = fs::symlink_metadata(trusted_install_root)
        .map_err(|_| "CodeMode install root is unavailable".to_owned())?;
    if root_link.file_type().is_symlink()
        || !root_link.is_dir()
        || root_link.uid() != unsafe { libc::geteuid() }
        || root_link.mode() & 0o077 != 0
        || fs::canonicalize(trusted_install_root).ok().as_deref() != Some(trusted_install_root)
    {
        return Err("CodeMode install root must be a canonical owner-only directory".to_owned());
    }
    let manifest_path = trusted_install_root.join(CODEMODE_HELPER_MANIFEST_FILE);
    let manifest_link = match fs::symlink_metadata(&manifest_path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return unavailable(),
        Err(_) => return Err("CodeMode manifest cannot be inspected".to_owned()),
    };
    if manifest_link.file_type().is_symlink()
        || !manifest_link.is_file()
        || manifest_link.uid() != unsafe { libc::geteuid() }
        || manifest_link.mode() & 0o077 != 0
        || manifest_link.len() > MAX_CODEMODE_HELPER_MANIFEST_BYTES as u64
    {
        return Err("CodeMode manifest must be a bounded owner-only regular file".to_owned());
    }
    let mut file = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC)
        .open(&manifest_path)
        .map_err(|_| "CodeMode manifest cannot be opened safely".to_owned())?;
    let opened = file.metadata().map_err(|_| "CodeMode manifest metadata is unavailable".to_owned())?;
    if opened.dev() != manifest_link.dev()
        || opened.ino() != manifest_link.ino()
        || opened.uid() != unsafe { libc::geteuid() }
        || opened.mode() & 0o077 != 0
        || opened.len() > MAX_CODEMODE_HELPER_MANIFEST_BYTES as u64
    {
        return Err("CodeMode manifest changed while opening".to_owned());
    }
    let mut bytes = Vec::with_capacity(opened.len() as usize);
    file.take((MAX_CODEMODE_HELPER_MANIFEST_BYTES + 1) as u64)
        .read_to_end(&mut bytes)
        .map_err(|_| "CodeMode manifest cannot be read".to_owned())?;
    if bytes.len() > MAX_CODEMODE_HELPER_MANIFEST_BYTES {
        return Err("CodeMode manifest exceeds its bound".to_owned());
    }
    let manifest: CodeModeHelperManifestV1 = serde_json::from_slice(&bytes)
        .map_err(|_| "CodeMode manifest schema is invalid".to_owned())?;
    if manifest.schema_version != 1
        || manifest.helper_selector != crate::terminal_process::CodeModeHelperPackageV1::SELECTOR
        || manifest.relative_entrypoint != "codemode-helper.js"
    {
        return Err("CodeMode manifest identity is invalid".to_owned());
    }
    let package_arch = match std::env::consts::ARCH {
        "x86_64" => "x64",
        "aarch64" => "arm64",
        other => other,
    };
    let expected_target = format!("linux-{package_arch}-gnu");
    if manifest.status == "unavailable" {
        if manifest.sha256.is_some() || manifest.reason.as_deref().is_none_or(str::is_empty) {
            return Err("unavailable CodeMode manifest is malformed".to_owned());
        }
        return Ok(None);
    }
    if manifest.status != "available"
        || manifest.target != expected_target
        || manifest.reason.is_some()
    {
        return Ok(None);
    }
    let Some(expected_digest) = manifest.sha256.as_deref() else {
        return Err("available CodeMode manifest has no helper digest".to_owned());
    };
    if !crate::guard::is_sha256_digest(expected_digest) {
        return Err("CodeMode helper digest is malformed".to_owned());
    }
    let package = crate::terminal_process::CodeModeHelperPackageV1::resolve(
        trusted_selectors,
        trusted_install_root,
        Path::new(&manifest.relative_entrypoint),
        expected_digest,
    )
    .map_err(|_| "trusted CodeMode helper package failed integrity validation".to_owned())?;
    Ok(Some(package))
}

#[derive(Clone, Debug, Default)]
struct ExecutionSelectorRegistryV1 {
    selectors: BTreeMap<String, PathBuf>,
}

impl ExecutionSelectorRegistryV1 {
    fn load_from_state_dir(state_dir: &Path) -> Result<Self, String> {
        let path = state_dir.join(EXECUTION_SELECTOR_CONFIG_FILE);
        let metadata = match fs::symlink_metadata(&path) {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                return Ok(Self::default());
            }
            Err(_) => return Err("execution selector config cannot be inspected".to_owned()),
        };
        if metadata.file_type().is_symlink()
            || !metadata.is_file()
            || metadata.uid() != unsafe { libc::geteuid() }
            || metadata.mode() & 0o077 != 0
            || metadata.len() > MAX_EXECUTION_SELECTOR_CONFIG_BYTES as u64
        {
            return Err("execution selector config must be an owner-only bounded regular file".to_owned());
        }
        let mut file = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC)
            .open(&path)
            .map_err(|_| "execution selector config cannot be opened safely".to_owned())?;
        let opened = file.metadata().map_err(|_| "execution selector config metadata is unavailable".to_owned())?;
        if opened.dev() != metadata.dev()
            || opened.ino() != metadata.ino()
            || opened.uid() != unsafe { libc::geteuid() }
            || opened.mode() & 0o077 != 0
            || opened.len() > MAX_EXECUTION_SELECTOR_CONFIG_BYTES as u64
        {
            return Err("execution selector config changed while opening".to_owned());
        }
        let mut bytes = Vec::with_capacity(opened.len() as usize);
        file.take((MAX_EXECUTION_SELECTOR_CONFIG_BYTES + 1) as u64)
            .read_to_end(&mut bytes)
            .map_err(|_| "execution selector config cannot be read".to_owned())?;
        if bytes.len() > MAX_EXECUTION_SELECTOR_CONFIG_BYTES {
            return Err("execution selector config exceeds its bound".to_owned());
        }
        let entries = serde_json::from_slice::<Vec<ExecutionSelectorConfigV1>>(&bytes)
            .map_err(|_| "execution selector config is invalid".to_owned())?;
        if entries.len() > MAX_EXECUTION_SELECTORS {
            return Err("execution selector count exceeds its bound".to_owned());
        }
        let allowed = [
            "horizoncode:lsp:typescript-language-server",
            "horizoncode:lsp:rust-analyzer",
            "horizoncode:lsp:pyright-langserver",
            "horizoncode:lsp:pylsp",
            "horizoncode:dap:debugpy-adapter",
            "horizoncode:dap:lldb-dap",
            "horizoncode:repl:python3",
            "horizoncode:repl:node",
            crate::terminal_process::CodeModeHelperPackageV1::SELECTOR,
        ];
        let mut selectors = BTreeMap::new();
        for entry in entries {
            if !allowed.contains(&entry.selector.as_str())
                || !entry.executable.is_absolute()
                || selectors.contains_key(&entry.selector)
            {
                return Err("execution selector mapping is invalid or duplicated".to_owned());
            }
            let link = fs::symlink_metadata(&entry.executable)
                .map_err(|_| "configured execution selector is unavailable".to_owned())?;
            if link.file_type().is_symlink() || !link.is_file() {
                return Err("configured execution selector must name a regular executable".to_owned());
            }
            let canonical = fs::canonicalize(&entry.executable)
                .map_err(|_| "configured execution selector cannot be canonicalized".to_owned())?;
            if canonical != entry.executable {
                return Err("configured execution selector must be canonical".to_owned());
            }
            #[cfg(unix)]
            if link.permissions().mode() & 0o111 == 0 {
                return Err("configured execution selector is not executable".to_owned());
            }
            selectors.insert(entry.selector, canonical);
        }
        Ok(Self { selectors })
    }

    fn paths(&self) -> &BTreeMap<String, PathBuf> {
        &self.selectors
    }
}

#[derive(Clone, Debug)]
struct RegisteredVerifierCriterionProfileV1 {
    test_identity: String,
    argv: Vec<OsString>,
}

#[derive(Clone, Debug)]
struct RegisteredVerifierProfileV1 {
    profile_id: String,
    revision: u64,
    principal: String,
    executable: PathBuf,
    executable_digest: String,
    profile_digest: String,
    sandbox_policy_digest: String,
    environment: BTreeMap<OsString, OsString>,
    criteria: BTreeMap<String, RegisteredVerifierCriterionProfileV1>,
    max_duration: Duration,
    max_output_bytes: usize,
}

impl RegisteredVerifierProfileV1 {
    fn principal(&self) -> &str {
        &self.principal
    }

    fn criteria(&self) -> &BTreeMap<String, RegisteredVerifierCriterionProfileV1> {
        &self.criteria
    }

    fn validate_executable_at_launch(&self) -> Result<(), String> {
        let canonical = fs::canonicalize(&self.executable)
            .map_err(|_| "verifier executable is unavailable".to_owned())?;
        if canonical != self.executable
            || crate::terminal_process::executable_digest(&canonical)
                .map_err(|_| "verifier executable is unavailable".to_owned())?
                != self.executable_digest
        {
            return Err("verifier executable changed after profile registration".to_owned());
        }
        Ok(())
    }
}

/// Immutable verifier profile snapshot loaded from the private HostKernel state
/// directory at construction. The snapshot cannot be changed by RPC or workspace input.
#[derive(Clone, Debug, Default)]
struct VerifierProfileRegistryV1 {
    profiles: BTreeMap<String, RegisteredVerifierProfileV1>,
}

impl VerifierProfileRegistryV1 {
    fn from_local_config(
        configs: impl IntoIterator<Item = VerifierProfileConfigV1>,
    ) -> Result<Self, String> {
        let mut profiles = BTreeMap::new();
        for config in configs {
            let profile = validate_verifier_profile(config)?;
            if profiles
                .insert(profile.profile_id.clone(), profile)
                .is_some()
            {
                return Err("duplicate verifier profile ID".to_owned());
            }
        }
        if profiles.len() > MAX_VERIFIER_PROFILES {
            return Err("verifier profile count exceeds bounds".to_owned());
        }
        Ok(Self { profiles })
    }

    fn load_from_state_dir(state_dir: &Path) -> Result<Self, String> {
        let path = state_dir.join(VERIFIER_PROFILE_CONFIG_FILE);
        let metadata = match fs::symlink_metadata(&path) {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                return Ok(Self::default());
            }
            Err(_) => return Err("verifier profile config cannot be inspected".to_owned()),
        };
        if metadata.file_type().is_symlink()
            || !metadata.is_file()
            || metadata.uid() != unsafe { libc::geteuid() }
            || metadata.mode() & 0o077 != 0
            || metadata.len() > MAX_VERIFIER_PROFILE_CONFIG_BYTES as u64
        {
            return Err(
                "verifier profile config must be an owner-only bounded regular file".to_owned(),
            );
        }
        let mut file = std::fs::OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC)
            .open(&path)
            .map_err(|_| "verifier profile config cannot be opened safely".to_owned())?;
        let opened = file
            .metadata()
            .map_err(|_| "verifier profile config metadata is unavailable".to_owned())?;
        if opened.dev() != metadata.dev()
            || opened.ino() != metadata.ino()
            || opened.uid() != unsafe { libc::geteuid() }
            || opened.mode() & 0o077 != 0
            || opened.len() > MAX_VERIFIER_PROFILE_CONFIG_BYTES as u64
        {
            return Err("verifier profile config changed during secure open".to_owned());
        }
        let mut bytes = Vec::with_capacity(opened.len() as usize);
        file.take((MAX_VERIFIER_PROFILE_CONFIG_BYTES + 1) as u64)
            .read_to_end(&mut bytes)
            .map_err(|_| "verifier profile config cannot be read".to_owned())?;
        if bytes.len() > MAX_VERIFIER_PROFILE_CONFIG_BYTES {
            return Err("verifier profile config exceeds bounds".to_owned());
        }
        #[derive(Deserialize)]
        #[serde(deny_unknown_fields)]
        struct ConfigFileV1 {
            version: u64,
            profiles: Vec<VerifierProfileConfigV1>,
        }
        let config: ConfigFileV1 = serde_json::from_slice(&bytes)
            .map_err(|_| "verifier profile config is invalid".to_owned())?;
        if config.version != 1 || config.profiles.len() > MAX_VERIFIER_PROFILES {
            return Err("verifier profile config version or count is invalid".to_owned());
        }
        Self::from_local_config(config.profiles)
    }

    fn profile(&self, profile_id: &str) -> Option<&RegisteredVerifierProfileV1> {
        self.profiles.get(profile_id)
    }

    fn profile_for_run(
        &self,
        accepted_criteria: &[String],
        excluded_principals: &HashSet<String>,
    ) -> Option<&RegisteredVerifierProfileV1> {
        let accepted: std::collections::BTreeSet<&str> =
            accepted_criteria.iter().map(String::as_str).collect();
        let mut eligible = self.profiles.values().filter(|profile| {
            !excluded_principals.contains(&profile.principal)
                && profile
                    .criteria
                    .keys()
                    .map(String::as_str)
                    .collect::<std::collections::BTreeSet<_>>()
                    == accepted
        });
        let selected = eligible.next()?;
        eligible.next().is_none().then_some(selected)
    }
}

