    pub(crate) fn goal_id(&self) -> &str { &self.goal_id }
    pub(crate) fn run_id(&self) -> &str { &self.run_id }
    pub(crate) fn task_id(&self) -> &str { &self.task_id }
    pub(crate) fn attempt_id(&self) -> &str { &self.attempt_id }
