fn secret_provider_mismatch() -> HostError {
    (
        "secret_provider_mismatch",
        ErrorCategoryV1::Conflict,
        "secret target belongs to a different provider",
    )
}

fn secret_revoked() -> HostError {
    (
        "secret_revoked",
        ErrorCategoryV1::Conflict,
        "secret target is revoked and cannot be used",
    )
}

fn secret_use_expired() -> HostError {
    (
        "expired",
        ErrorCategoryV1::Authorization,
        "secret use expiry is in the past or outside the authorized window",
    )
}

fn secret_use_conflict() -> HostError {
    (
        "secret_conflict",
        ErrorCategoryV1::Conflict,
        "secret use idempotency or target binding conflicts with durable state",
    )
}

fn secret_use_consumed() -> HostError {
    (
        "secret_use_consumed",
        ErrorCategoryV1::Conflict,
        "secret use lease was already redeemed and cannot be reused",
    )
}

fn secret_use_journal_error(error: crate::secret_use::SecretUseJournalErrorV1) -> HostError {
    use crate::secret_use::SecretUseJournalErrorV1 as E;
    match error {
        E::NotFound => secret_mutation_not_found(),
        E::Conflict => secret_use_conflict(),
        E::Expired => secret_use_expired(),
        E::Consumed => secret_use_consumed(),
        E::Unsettled => secret_mutation_unknown(),
        E::Invalid => invalid(),
        E::Capacity | E::Persistence(_) | E::Corrupt => secret_mutation_unavailable(),
    }
}

fn secret_mutation_unavailable() -> HostError {
    (
        "secret_unavailable",
        ErrorCategoryV1::Unavailable,
        "secret mutation journal or effect authority is unavailable",
    )
}

fn secret_mutation_denied() -> HostError {
    (
        "secret_denied",
        ErrorCategoryV1::Authorization,
        "Guard denied the secret mutation grant",
    )
}

fn secret_mutation_conflict() -> HostError {
    (
        "secret_conflict",
        ErrorCategoryV1::Conflict,
        "secret mutation idempotency or target binding conflicts with durable state",
    )
}

fn secret_mutation_unknown() -> HostError {
    (
        "secret_outcome_unknown",
        ErrorCategoryV1::Uncertain,
        "secret mutation outcome is UNKNOWN and must not be retried",
    )
}

fn secret_mutation_stale() -> HostError {
    (
        "secret_stale_version",
        ErrorCategoryV1::Conflict,
        "secret target version is stale; prepare a new exact mutation",
    )
}

fn secret_mutation_not_found() -> HostError {
    (
        "secret_not_found",
        ErrorCategoryV1::NotFound,
        "secret target was not found in the authenticated owner scope",
    )
}

fn secret_journal_error(error: crate::secret_mutation::SecretJournalErrorV1) -> HostError {
    use crate::secret_mutation::SecretJournalErrorV1 as E;
    match error {
        E::NotFound => secret_mutation_not_found(),
        E::StaleVersion { .. } => secret_mutation_stale(),
        E::ProviderMismatch => (
            "secret_provider_mismatch",
            ErrorCategoryV1::Conflict,
            "secret target belongs to a different provider",
        ),
        E::Revoked => (
            "secret_revoked",
            ErrorCategoryV1::Conflict,
            "secret target is revoked and cannot be mutated",
        ),
        E::IdempotencyConflict => secret_mutation_conflict(),
        E::Unsettled => secret_mutation_unknown(),
        E::Invalid => invalid(),
        E::Capacity | E::Persistence(_) | E::Corrupt => secret_mutation_unavailable(),
    }
}
fn checkpoint_preview_value(preview: &crate::checkpoint::CheckpointRestorePreviewV1) -> Value {
    use crate::checkpoint::{CheckpointFileKindV1, CheckpointRestoreModeV1, RestoreConflictKindV1};
    let mode = match preview.mode { CheckpointRestoreModeV1::Full => "FULL", CheckpointRestoreModeV1::SelectedPaths => "SELECTED_PATHS" };
    let conflicts = preview.conflicts.iter().map(|conflict| {
        let kind = match conflict.kind {
            RestoreConflictKindV1::WorkspaceRevisionChanged => "WORKSPACE_REVISION_CHANGED",
            RestoreConflictKindV1::DirtyPath => "DIRTY_PATH",
            RestoreConflictKindV1::UntrackedPath => "UNTRACKED_PATH",
            RestoreConflictKindV1::WorkspaceStatusUnavailable => "WORKSPACE_STATUS_UNAVAILABLE",
            RestoreConflictKindV1::UnsafePath => "UNSAFE_PATH",
        };
        map_value([("path", conflict.path.clone().map(Value::String).unwrap_or(Value::Nil)),
            ("kind", Value::String(kind.to_owned()))])
    }).collect();
    let actions = preview.actions.iter().map(|action| {
        let kind = match action.target.kind { CheckpointFileKindV1::RegularFile => "REGULAR_FILE", CheckpointFileKindV1::Absent => "ABSENT" };
        map_value([("path", Value::String(action.path.clone())),
            ("expectedBeforeDigest", action.expected_before_digest.clone().map(Value::String).unwrap_or(Value::Nil)),
            ("target", map_value([("kind", Value::String(kind.to_owned())),
                ("digest", action.target.digest.clone().map(Value::String).unwrap_or(Value::Nil)),
                ("byteLength", Value::Unsigned(action.target.byte_length)),
                ("executable", Value::Bool(action.target.executable)),
                ("linkCount", Value::Unsigned(action.target.link_count))]))])
    }).collect();
    map_value([("checkpointID", Value::String(preview.checkpoint_id.clone())),
        ("checkpointArtifact", map_value([
            ("artifactID", Value::String(preview.checkpoint_artifact.artifact_id.clone())),
            ("digest", Value::String(preview.checkpoint_artifact.digest.clone())),
            ("byteLength", Value::String(preview.checkpoint_artifact.byte_length.clone())),
            ("mediaType", Value::String(preview.checkpoint_artifact.media_type.clone())),
            ("classification", Value::String(preview.checkpoint_artifact.classification.clone())),
        ])),
        ("workspaceRevision", Value::String(preview.observed_revision.clone())),
        ("workspaceRevisionChanged", Value::Bool(preview.workspace_revision_changed)),
        ("mode", Value::String(mode.to_owned())),
        ("selectedPaths", Value::Array(preview.selected_paths.iter().cloned().map(Value::String).collect())),
        ("actions", Value::Array(actions)), ("conflicts", Value::Array(conflicts)),
        ("previewDigest", Value::String(preview.preview_digest.clone()))])
}

fn map_value<const N: usize>(items: [(&str, Value); N]) -> Value {
    Value::Map(
        items
            .into_iter()
            .map(|(key, value)| (key.to_owned(), value))
            .collect(),
    )
}

fn map_value_vec(items: Vec<(&str, Value)>) -> Value {
    Value::Map(items.into_iter().map(|(key, value)| (key.to_owned(), value)).collect())
}

fn host_random_id(prefix: &str) -> Result<String, HostError> {
    let mut entropy = [0_u8; 32];
    File::open("/dev/urandom")
        .and_then(|mut random| random.read_exact(&mut entropy))
        .map_err(|_| {
            (
                "effect_unavailable",
                ErrorCategoryV1::Unavailable,
                "host verifier identity entropy is unavailable",
            )
        })?;
    Ok(format!("{prefix}_{}", blake3::hash(&entropy).to_hex()))
}

fn verifier_owner_delivery_id(verification_run_id: &str, subject: &str, purpose: &str) -> String {
    let digest = blake3::hash(format!("{verification_run_id}\0{subject}\0{purpose}").as_bytes());
    format!("verifier-{purpose}-{}", &digest.to_hex()[..32])
}

fn verifier_approved_arguments_digest(
    goal_id: &str,
    run_id: &str,
    spec_id: &str,
    spec_digest: &str,
    verification_run_id: &str,
    profile: &RegisteredVerifierProfileV1,
    criterion_id: &str,
    criterion: &RegisteredVerifierCriterionProfileV1,
    reviewer_principal: &str,
    owner_epoch: u64,
    cancel_generation: u64,
    location_id: &str,
    location: &RegisteredLocation,
    final_revision: &str,
) -> Result<String, HostError> {
    let launch_spec = verifier_launch_spec(profile, criterion, location, final_revision);
    let source = crate::host_kernel::managed_verifier::VerifierInvocationSourceV1 {
        goal_id: goal_id.to_owned(),
        run_id: run_id.to_owned(),
        spec_id: spec_id.to_owned(),
        spec_digest: spec_digest.to_owned(),
        verification_run_id: verification_run_id.to_owned(),
        criterion_id: criterion_id.to_owned(),
        challenge_set_digest: String::new(),
        canonical_arguments_digest: String::new(),
        reviewer_principal: reviewer_principal.to_owned(),
        execution_principal: profile.principal.clone(),
        profile_id: profile.profile_id.clone(),
        profile_revision: profile.revision,
        profile_digest: profile.profile_digest.clone(),
        executable_digest: profile.executable_digest.clone(),
        sandbox_policy_digest: profile.sandbox_policy_digest.clone(),
        test_identity: criterion.test_identity.clone(),
        cancel_generation,
        binding: crate::terminal_process::StdioExecutionBindingV1 {
            execution_id: String::new(),
            effect_id: String::new(),
            challenge_id: String::new(),
            principal: reviewer_principal.to_owned(),
            execution_principal: profile.principal.clone(),
            scope: crate::terminal_process::StdioExecutionScopeV1::Session { session_id: String::new() },
            session_id: String::new(),
            location_id: location_id.to_owned(),
            capability_id: crate::guard::BUILTIN_VERIFIER_ID.to_owned(),
            capability_lease_digest: String::new(),
            approved_arguments_digest: String::new(),
            attempt_scope_digest: None,
            owner_epoch,
            generation: 1,
            workspace_revision: final_revision.to_owned(),
            profile_ref: profile.profile_id.clone(),
            profile_id: profile.profile_id.clone(),
            profile_revision: profile.revision,
            profile_digest: profile.profile_digest.clone(),
            executable_digest: profile.executable_digest.clone(),
            dap_allow_evaluate: false,
        },
        launch_spec,
    };
    crate::host_kernel::managed_verifier::VerifierInvocationV1::approved_arguments_digest_for(
        &source,
    )
    .map_err(|_| {
        (
            "invalid_verifier_invocation",
            ErrorCategoryV1::Authorization,
            "verifier invocation failed canonical authority validation",
        )
    })
}

fn verifier_launch_spec(
    profile: &RegisteredVerifierProfileV1,
    criterion: &RegisteredVerifierCriterionProfileV1,
    location: &RegisteredLocation,
    final_revision: &str,
) -> crate::terminal_process::StdioLaunchSpec {
    let mut launch = crate::terminal_process::StdioLaunchSpec::new(
        profile.executable.clone(),
        profile.executable_digest.clone(),
        criterion.argv.clone(),
        location.canonical_root.clone(),
    );
    launch.profile_digest = profile.profile_digest.clone();
    launch.workspace_revision = final_revision.to_owned();
    launch.workspace_root = location.canonical_root.clone();
    launch.env = profile.environment.clone();
    launch.timeout = profile.max_duration;
    launch.max_output_bytes = profile.max_output_bytes;
    launch
}

fn managed_verifier_invocation(
    set: &VerifierChallengeSetV1,
    member: &VerifierChallengeMemberV1,
    location: &RegisteredLocation,
    execution_id: String,
    generation: u64,
    attempt_scope: &ManagedAttemptScopeV1,
) -> Result<crate::host_kernel::managed_verifier::VerifierInvocationV1, HostError> {
    // Reconstructing an immutable invocation also serves reconciliation after
    // expiry. Dispatch checks the current durable lease in EffectHost; expiration
    // must never prevent looking up a possibly dispatched execution.
    if generation == 0 {
        return Err(managed_conflict("verifier execution generation is invalid"));
    }
    let attempt_scope_digest = attempt_scope.digest().map_err(|_| invalid())?;
    if attempt_scope.goal_id != set.goal_id
        || attempt_scope.run_id != set.run_id
        || attempt_scope.attempt_id != set.attempt_id
        || attempt_scope.location_id != set.location_id
        || attempt_scope.owner_epoch != set.owner_epoch
        || attempt_scope.workspace_revision != set.final_revision
    {
        return Err(VERIFIER_RECOVERY_REQUIRED);
    }
    let criterion = set
        .verifier_profile
        .criteria
        .get(&member.criterion_id)
        .ok_or(managed_conflict(
            "retained verifier profile no longer contains the criterion",
        ))?;
    let lease_digest = member.lease_digest.as_ref().ok_or(managed_conflict(
        "verifier challenge has no approved one-use lease",
    ))?;
    let binding = crate::terminal_process::StdioExecutionBindingV1 {
        execution_id,
        effect_id: member.effect_id.clone(),
        challenge_id: member.challenge_id.clone(),
        principal: set.reviewer_principal.clone(),
        execution_principal: set.verifier_profile.principal.clone(),
        scope: crate::terminal_process::StdioExecutionScopeV1::Session {
            session_id: attempt_scope.session_id.clone(),
        },
        session_id: attempt_scope.session_id.clone(),
        location_id: set.location_id.clone(),
        capability_id: crate::guard::BUILTIN_VERIFIER_ID.to_owned(),
        capability_lease_digest: lease_digest.clone(),
        approved_arguments_digest: member.input_digest.clone(),
        attempt_scope_digest: Some(attempt_scope_digest),
        owner_epoch: set.owner_epoch,
        generation,
        workspace_revision: set.final_revision.clone(),
        profile_ref: set.verifier_profile.profile_id.clone(),
        profile_id: set.verifier_profile.profile_id.clone(),
        profile_revision: set.verifier_profile.revision,
        profile_digest: set.verifier_profile.profile_digest.clone(),
        executable_digest: set.verifier_profile.executable_digest.clone(),
        dap_allow_evaluate: false,
    };
    let source = crate::host_kernel::managed_verifier::VerifierInvocationSourceV1 {
        goal_id: set.goal_id.clone(),
        run_id: set.run_id.clone(),
        spec_id: set.spec_id.clone(),
        spec_digest: set.spec_digest.clone(),
        verification_run_id: set.verification_run_id.clone(),
        criterion_id: member.criterion_id.clone(),
        challenge_set_digest: set.challenge_set_digest.clone(),
        canonical_arguments_digest: member.canonical_arguments_digest.clone(),
        reviewer_principal: set.reviewer_principal.clone(),
        execution_principal: set.verifier_profile.principal.clone(),
        profile_id: set.verifier_profile.profile_id.clone(),
        profile_revision: set.verifier_profile.revision,
        profile_digest: set.verifier_profile.profile_digest.clone(),
        executable_digest: set.verifier_profile.executable_digest.clone(),
        sandbox_policy_digest: set.verifier_profile.sandbox_policy_digest.clone(),
        test_identity: criterion.test_identity.clone(),
        cancel_generation: set.cancel_generation,
        binding,
        launch_spec: verifier_launch_spec(
            &set.verifier_profile,
            criterion,
            location,
            &set.final_revision,
        ),
    };
    crate::host_kernel::managed_verifier::VerifierInvocationV1::new(source).map_err(|_| {
        (
            "invalid_verifier_invocation",
            ErrorCategoryV1::Authorization,
            "retained verifier authority no longer matches the approved challenge",
        )
    })
}

fn parse_verifier_challenge_members(
    prepared: &[Value],
    accepted_criteria: &[String],
) -> Result<Vec<VerifierChallengeMemberV1>, HostError> {
    if prepared.len() != accepted_criteria.len() || prepared.is_empty() || prepared.len() > 32 {
        return Err(invalid());
    }
    let mut members = Vec::with_capacity(prepared.len());
    for (value, expected_criterion) in prepared.iter().zip(accepted_criteria) {
        let fields = match value {
            Value::Map(fields) => fields,
            _ => return Err(invalid()),
        };
        let call_id = get_text(fields, "callId")?;
        let challenge_id = get_text(fields, "challengeId")?;
        let effect_id = get_text(fields, "effectId")?;
        let input_digest = get_text(fields, "inputDigest")?;
        let expires_at_unix_ms = get_unsigned(fields, "expiresAtUnixMs")?;
        let normalized_targets = match fields.get("normalizedTargets") {
            Some(Value::Array(targets)) if !targets.is_empty() && targets.len() <= 64 => {
                targets.clone()
            }
            _ => return Err(invalid()),
        };
        if call_id != expected_criterion
            || !valid_verifier_id(challenge_id)
            || !valid_verifier_id(effect_id)
            || !is_blake3_digest(input_digest)
            || expires_at_unix_ms <= current_unix_ms()
        {
            return Err(invalid());
        }
        members.push(VerifierChallengeMemberV1 {
            criterion_id: expected_criterion.clone(),
            challenge_id: challenge_id.to_owned(),
            effect_id: effect_id.to_owned(),
            input_digest: input_digest.to_owned(),
            canonical_arguments_digest: String::new(),
            expires_at_unix_ms,
            normalized_targets,
            lease_digest: None,
            execution_id: None,
            execution_generation: None,
        });
    }
    Ok(members)
}

fn verifier_challenge_set_digest(
    goal_id: &str,
    run_id: &str,
    spec_id: &str,
    spec_digest: &str,
    verification_run_id: &str,
    attempt_id: &str,
    owner_epoch: u64,
    cancel_generation: u64,
    reviewer: &str,
    profile_id: &str,
    profile_digest: &str,
    location_id: &str,
    final_revision: &str,
    members: &[VerifierChallengeMemberV1],
) -> Result<String, HostError> {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"horizoncode.managed-verifier-challenge-set.v1\0");
    for value in [
        goal_id,
        run_id,
        spec_id,
        spec_digest,
        verification_run_id,
        attempt_id,
        reviewer,
        profile_id,
        profile_digest,
        location_id,
        final_revision,
    ] {
        hasher.update(&(value.len() as u64).to_be_bytes());
        hasher.update(value.as_bytes());
    }
    hasher.update(&owner_epoch.to_be_bytes());
    hasher.update(&cancel_generation.to_be_bytes());
    for member in members {
        for value in [
            member.criterion_id.as_str(),
            member.challenge_id.as_str(),
            member.effect_id.as_str(),
            member.input_digest.as_str(),
            member.canonical_arguments_digest.as_str(),
        ] {
            hasher.update(&(value.len() as u64).to_be_bytes());
            hasher.update(value.as_bytes());
        }
        hasher.update(&member.expires_at_unix_ms.to_be_bytes());
        let targets = crate::messagepack::encode(
            &Value::Array(member.normalized_targets.clone()),
            crate::messagepack::FRAME_LIMITS,
        )
        .map_err(|_| invalid())?;
        hasher.update(&(targets.len() as u64).to_be_bytes());
        hasher.update(&targets);
    }
    Ok(format!("blake3:{}", hasher.finalize().to_hex()))
}

/// Stable HostKernel identity for an exact verifier admission request. This key is
/// derived only after all authority pins and the frozen evidence plan have been
/// resolved from authenticated HostKernel/OwnerLog state; RPC delivery IDs are not
/// inputs and cannot choose or rebind the set.
#[allow(clippy::too_many_arguments)]
fn verifier_set_identity_digest(
    goal_id: &str,
    run_id: &str,
    task_id: &str,
    attempt_id: &str,
    owner_epoch: u64,
    managed_revision: u64,
    spec_id: &str,
    spec_digest: &str,
    profile: &RegisteredVerifierProfileV1,
    reviewer: &str,
    location_id: &str,
    canonical_root: &str,
    final_revision: &str,
    receipt_basis_digest: &str,
    evidence_plan_digest: &str,
    cancel_generation: u64,
) -> Result<String, HostError> {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"horizoncode.managed-verifier-set-identity.v1\0");
    for value in [
        goal_id,
        run_id,
        task_id,
        attempt_id,
        spec_id,
        spec_digest,
        &profile.profile_id,
        &profile.principal,
        &profile.profile_digest,
        &profile.executable_digest,
        &profile.sandbox_policy_digest,
        reviewer,
        location_id,
        canonical_root,
        final_revision,
        receipt_basis_digest,
        evidence_plan_digest,
    ] {
        hasher.update(&(value.len() as u64).to_be_bytes());
        hasher.update(value.as_bytes());
    }
    hasher.update(&owner_epoch.to_be_bytes());
    hasher.update(&managed_revision.to_be_bytes());
    hasher.update(&profile.revision.to_be_bytes());
    hasher.update(&cancel_generation.to_be_bytes());
    Ok(format!("blake3:{}", hasher.finalize().to_hex()))
}

fn verifier_evidence_plan_digest(
    evidence_plan: &[(String, RegisteredVerifierCriterionProfileV1)],
) -> String {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"horizoncode.managed-verifier-evidence-plan.v1\0");
    hasher.update(&(evidence_plan.len() as u64).to_be_bytes());
    for (criterion_id, criterion) in evidence_plan {
        for value in [criterion_id.as_str(), criterion.test_identity.as_str()] {
            hasher.update(&(value.len() as u64).to_be_bytes());
            hasher.update(value.as_bytes());
        }
        hasher.update(&(criterion.argv.len() as u64).to_be_bytes());
        for argument in &criterion.argv {
            let value = argument.to_string_lossy();
            hasher.update(&(value.len() as u64).to_be_bytes());
            hasher.update(value.as_bytes());
        }
    }
    format!("blake3:{}", hasher.finalize().to_hex())
}

fn verifier_journal_entry(
    set: &VerifierChallengeSetV1,
) -> Result<verifier_journal::VerifierJournalEntryV1, HostError> {
    use verifier_journal::{
        VerifierJournalEntryV1, VerifierJournalMemberV1, VerifierJournalStateV1,
    };
    let state = match set.state {
        VerifierChallengeSetStateV1::AwaitingApproval => VerifierJournalStateV1::AwaitingApproval,
        VerifierChallengeSetStateV1::Approved => VerifierJournalStateV1::Approved,
        VerifierChallengeSetStateV1::Aborted => VerifierJournalStateV1::Aborted,
        VerifierChallengeSetStateV1::Executing => VerifierJournalStateV1::Dispatching,
        VerifierChallengeSetStateV1::Unknown => VerifierJournalStateV1::Unknown,
        VerifierChallengeSetStateV1::Settled => VerifierJournalStateV1::Settled,
    };
    let members = set
        .members
        .iter()
        .map(|member| {
            let target_bytes = crate::messagepack::encode(
                &Value::Array(member.normalized_targets.clone()),
                crate::messagepack::FRAME_LIMITS,
            )
            .map_err(|_| invalid())?;
            let member_state = match state {
                VerifierJournalStateV1::AwaitingApproval => {
                    VerifierJournalStateV1::AwaitingApproval
                }
                VerifierJournalStateV1::Approved => VerifierJournalStateV1::Approved,
                VerifierJournalStateV1::Dispatching => {
                    if member.execution_id.is_some() {
                        VerifierJournalStateV1::Dispatching
                    } else {
                        VerifierJournalStateV1::Approved
                    }
                }
                VerifierJournalStateV1::Unknown => {
                    if member.execution_id.is_some() {
                        VerifierJournalStateV1::Unknown
                    } else {
                        VerifierJournalStateV1::Approved
                    }
                }
                VerifierJournalStateV1::Settled => VerifierJournalStateV1::Settled,
                VerifierJournalStateV1::Aborted => VerifierJournalStateV1::Aborted,
            };
            Ok(VerifierJournalMemberV1 {
                criterion_id: member.criterion_id.clone(),
                challenge_id: member.challenge_id.clone(),
                effect_id: member.effect_id.clone(),
                guard_argument_digest: member.input_digest.clone(),
                canonical_content_digest: member.canonical_arguments_digest.clone(),
                expires_at_unix_ms: member.expires_at_unix_ms,
                normalized_targets_hex: encode_hex(&target_bytes),
                lease_digest: member.lease_digest.clone(),
                execution_id: member.execution_id.clone(),
                execution_generation: member.execution_generation,
                state: member_state,
            })
        })
        .collect::<Result<Vec<_>, HostError>>()?;
    Ok(VerifierJournalEntryV1 {
        goal_id: set.goal_id.clone(),
        run_id: set.run_id.clone(),
        spec_id: set.spec_id.clone(),
        spec_digest: set.spec_digest.clone(),
        verification_run_id: set.verification_run_id.clone(),
        set_identity_digest: set.set_identity_digest.clone(),
        managed_revision: set.managed_revision,
        receipt_basis_digest: set.receipt_basis_digest.clone(),
        evidence_plan_digest: set.evidence_plan_digest.clone(),
        attempt_id: set.attempt_id.clone(),
        challenge_set_digest: set.challenge_set_digest.clone(),
        owner_epoch: set.owner_epoch,
        cancel_generation: set.cancel_generation,
        delivery_id: set.delivery_id.clone(),
        reviewer_principal: set.reviewer_principal.clone(),
        profile_id: set.verifier_profile.profile_id.clone(),
        profile_digest: set.verifier_profile.profile_digest.clone(),
        location_id: set.location_id.clone(),
        final_revision: set.final_revision.clone(),
        created_at_unix_ms: set.created_at_unix_ms,
        state,
        members,
    })
}

fn encode_hex(bytes: &[u8]) -> String {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut output = String::with_capacity(bytes.len().saturating_mul(2));
    for byte in bytes {
        output.push(char::from(HEX[usize::from(byte >> 4)]));
        output.push(char::from(HEX[usize::from(byte & 0x0f)]));
    }
    output
}

fn decode_hex(value: &str) -> Result<Vec<u8>, HostError> {
    if value.len() % 2 != 0 || value.len() > 128 * 1024 {
        return Err(invalid());
    }
    value
        .as_bytes()
        .chunks_exact(2)
        .map(|pair| {
            let digit = |byte: u8| match byte {
                b'0'..=b'9' => Some(byte - b'0'),
                b'a'..=b'f' => Some(byte - b'a' + 10),
                _ => None,
            };
            Ok((digit(pair[0]).ok_or_else(invalid)? << 4) | digit(pair[1]).ok_or_else(invalid)?)
        })
        .collect()
}

fn verifier_challenge_set_response(
    set: &VerifierChallengeSetV1,
    snapshot: &ManagedSnapshot,
    locations: &HashMap<String, RegisteredLocation>,
) -> Result<Value, HostError> {
    let challenges = if set.state == VerifierChallengeSetStateV1::AwaitingApproval { set
        .members
        .iter()
        .map(|member| {
            let targets = Value::Array(member.normalized_targets.clone());
            let mut challenge = map_value([
                ("criterionID", Value::String(member.criterion_id.clone())),
                ("challengeID", Value::String(member.challenge_id.clone())),
                ("effectID", Value::String(member.effect_id.clone())),
                (
                    "capabilityID",
                    Value::String(crate::guard::BUILTIN_VERIFIER_ID.to_owned()),
                ),
                ("locationID", Value::String(set.location_id.clone())),
                ("inputDigest", Value::String(member.input_digest.clone())),
                ("normalizedTargets", targets.clone()),
                (
                    "expiresAtUnixMs",
                    Value::Unsigned(member.expires_at_unix_ms),
                ),
                (
                    "policySummary",
                    Value::String(format!(
                        "Run the host-registered verifier for accepted criterion {}",
                        member.criterion_id
                    )),
                ),
            ]);
            let Value::Map(fields) = &mut challenge else {
                return Err(invalid());
            };
            add_guard_consent_projection(
                fields,
                crate::guard::EffectOriginKindV1::ManagedRun,
                crate::guard::BUILTIN_VERIFIER_ID,
                &targets,
                Some(&set.run_id),
                None,
            )?;
            Ok(challenge)
        })
        .collect::<Result<Vec<_>, HostError>>()? } else { Vec::new() };
    let status = match set.state {
        VerifierChallengeSetStateV1::AwaitingApproval => "NEEDS_APPROVAL",
        VerifierChallengeSetStateV1::Approved => "RESUME_EXECUTION",
        VerifierChallengeSetStateV1::Executing => return Err(VERIFIER_RECOVERY_REQUIRED),
        VerifierChallengeSetStateV1::Unknown
        | VerifierChallengeSetStateV1::Aborted
        | VerifierChallengeSetStateV1::Settled => return Err(VERIFIER_RECOVERY_REQUIRED),
    };
    let location = locations.get(&set.location_id).ok_or(VERIFIER_RECOVERY_REQUIRED)?;
    let canonical_root = location.canonical_root.to_str().ok_or_else(invalid)?;
    let mut response = map_value([
        ("status", Value::String(status.to_owned())),
        ("goalID", Value::String(set.goal_id.clone())),
        ("runID", Value::String(set.run_id.clone())),
        ("taskID", Value::String(
            snapshot.attempts.get(&set.attempt_id).ok_or(VERIFIER_RECOVERY_REQUIRED)?.task_id.clone(),
        )),
        ("attemptID", Value::String(set.attempt_id.clone())),
        (
            "verificationRunID",
            Value::String(set.verification_run_id.clone()),
        ),
        ("setIdentityDigest", Value::String(set.set_identity_digest.clone())),
        (
            "challengeSetDigest",
            Value::String(set.challenge_set_digest.clone()),
        ),
        ("finalRevision", Value::String(set.final_revision.clone())),
        ("approvalLocation", map_value([
            ("locationID", Value::String(set.location_id.clone())),
            ("workspaceID", Value::String(location.workspace_id.clone())),
            ("canonicalRoot", Value::String(canonical_root.to_owned())),
            ("workspaceRevision", Value::String(set.final_revision.clone())),
        ])),
        ("evidenceDigest", Value::Nil),
        ("artifactRefs", Value::Array(Vec::new())),
        ("challenges", Value::Array(challenges)),
        ("revision", Value::Unsigned(snapshot.revision)),
    ]);
    let task_id = snapshot.attempts.get(&set.attempt_id).ok_or(VERIFIER_RECOVERY_REQUIRED)?.task_id.clone();
    insert_verifier_challenge_set_identity_fields(&mut response, set, &task_id)?;
    Ok(response)
}

/// Explicit versioned identity pins accompany every challenge-set projection.
/// Opaque set digests remain useful for equality, but Core and downstream
/// settlement owners must also be able to compare the authoritative fields to
/// their accepted SpecVersion, profile, Attempt and owner epoch after recovery.
fn insert_verifier_challenge_set_identity_fields(
    response: &mut Value,
    set: &VerifierChallengeSetV1,
    task_id: &str,
) -> Result<(), HostError> {
    let Value::Map(fields) = response else { return Err(invalid()) };
    fields.insert("schemaVersion".to_owned(), Value::Unsigned(1));
    fields.insert("goalID".to_owned(), Value::String(set.goal_id.clone()));
    fields.insert("runID".to_owned(), Value::String(set.run_id.clone()));
    fields.insert("taskID".to_owned(), Value::String(task_id.to_owned()));
    fields.insert("attemptID".to_owned(), Value::String(set.attempt_id.clone()));
    fields.insert("verificationRunID".to_owned(), Value::String(set.verification_run_id.clone()));
    fields.insert("challengeSetDigest".to_owned(), Value::String(set.challenge_set_digest.clone()));
    fields.insert("setIdentityDigest".to_owned(), Value::String(set.set_identity_digest.clone()));
    fields.insert("ownerEpoch".to_owned(), Value::String(set.owner_epoch.to_string()));
    fields.insert("specID".to_owned(), Value::String(set.spec_id.clone()));
    fields.insert("specDigest".to_owned(), Value::String(set.spec_digest.clone()));
    fields.insert("profileID".to_owned(), Value::String(set.verifier_profile.profile_id.clone()));
    fields.insert("profileRevision".to_owned(), Value::String(set.verifier_profile.revision.to_string()));
    fields.insert("profileDigest".to_owned(), Value::String(set.verifier_profile.profile_digest.clone()));
    fields.insert("finalRevision".to_owned(), Value::String(set.final_revision.clone()));
    fields.insert("evidencePlanDigest".to_owned(), Value::String(set.evidence_plan_digest.clone()));
    Ok(())
}

fn verifier_artifact_refs_value(
    evidence: &crate::managed_control::VerificationEvidenceV1,
) -> Value {
    Value::Array(evidence.criteria.iter().map(|criterion| {
        let refs = criterion.artifact_refs.iter().map(|reference| {
            let classification = match reference.classification {
                crate::protocol::ArtifactClassificationV1::Public => "PUBLIC",
                crate::protocol::ArtifactClassificationV1::Workspace => "WORKSPACE",
                crate::protocol::ArtifactClassificationV1::Sensitive => "SENSITIVE",
            };
            map_value([
                ("artifactID", Value::String(reference.artifact_id.clone())),
                ("digest", Value::String(reference.digest.clone())),
                ("byteLength", Value::String(reference.byte_length.clone())),
                ("mediaType", Value::String(reference.media_type.clone())),
                ("classification", Value::String(classification.to_owned())),
            ])
        }).collect();
        map_value([
            ("criterionID", Value::String(criterion.criterion_id.clone())),
            ("artifactRefs", Value::Array(refs)),
        ])
    }).collect())
}

#[cfg(test)]
mod verifier_challenge_retention_tests {
    use super::*;

    fn profile(profile_id: &str, principal: &str, digest: &str) -> RegisteredVerifierProfileV1 {
        RegisteredVerifierProfileV1 {
            profile_id: profile_id.to_owned(),
            revision: 1,
            principal: principal.to_owned(),
            executable: PathBuf::from("/bin/sh"),
            executable_digest: format!("blake3:{}", "a".repeat(64)),
            profile_digest: format!("blake3:{digest}"),
            sandbox_policy_digest: format!("blake3:{}", "b".repeat(64)),
            environment: BTreeMap::new(),
            criteria: BTreeMap::new(),
            max_duration: Duration::from_secs(1),
            max_output_bytes: 1024,
        }
    }

    fn challenge_set(
        state: VerifierChallengeSetStateV1,
        created_at_unix_ms: u64,
        verifier_profile: RegisteredVerifierProfileV1,
    ) -> VerifierChallengeSetV1 {
        VerifierChallengeSetV1 {
            goal_id: "goal-1".to_owned(),
            run_id: "run-1".to_owned(),
            spec_id: "spec-1".to_owned(),
            spec_digest: format!("blake3:{}", "c".repeat(64)),
            verification_run_id: format!("verification-{created_at_unix_ms}"),
            set_identity_digest: format!("blake3:{}", "9".repeat(64)),
            managed_revision: 3,
            receipt_basis_digest: format!("blake3:{}", "a".repeat(64)),
            evidence_plan_digest: format!("blake3:{}", "b".repeat(64)),
            attempt_id: "attempt-fixture".to_owned(),
            challenge_set_digest: format!("blake3:{}", "d".repeat(64)),
            owner_epoch: 3,
            cancel_generation: 4,
            delivery_id: format!("delivery-{created_at_unix_ms}"),
            reviewer_principal: "server_auth:reviewer".to_owned(),
            verifier_profile,
            location_id: "location-1".to_owned(),
            final_revision: format!("blake3:{}", "e".repeat(64)),
            created_at_unix_ms,
            members: Vec::new(),
            state,
        }
    }

    #[test]
    fn active_challenge_resume_requires_the_same_immutable_verifier_profile() {
        let set = challenge_set(
            VerifierChallengeSetStateV1::AwaitingApproval,
            10,
            profile("profile-1", "server_auth:verifier", &"f".repeat(64)),
        );
        let binding = |profile: RegisteredVerifierProfileV1| {
            verifier_set_can_resume_with_profile(
                &set,
                "goal-1",
                "run-1",
                "server_auth:reviewer",
                3,
                "spec-1",
                &format!("blake3:{}", "c".repeat(64)),
                &format!("blake3:{}", "e".repeat(64)),
                &profile,
            )
        };

        assert!(binding(profile(
            "profile-1",
            "server_auth:verifier",
            &"f".repeat(64)
        )));
        assert!(!binding(profile(
            "profile-1",
            "server_auth:verifier",
            &"0".repeat(64)
        )));
        assert!(!binding(profile(
            "different-profile",
            "server_auth:verifier",
            &"f".repeat(64)
        )));
        assert!(!binding(profile(
            "profile-1",
            "server_auth:other-verifier",
            &"f".repeat(64)
        )));

        let selected_profile = profile("profile-1", "server_auth:verifier", &"f".repeat(64));
        let resumes = |candidate: &VerifierChallengeSetV1| {
            verifier_set_can_resume_with_profile(
                candidate,
                "goal-1",
                "run-1",
                "server_auth:reviewer",
                3,
                "spec-1",
                &format!("blake3:{}", "c".repeat(64)),
                &format!("blake3:{}", "e".repeat(64)),
                &selected_profile,
            )
        };
        let mut stale = set.clone();
        stale.reviewer_principal = "server_auth:other-reviewer".to_owned();
        assert!(!resumes(&stale));
        let mut stale = set.clone();
        stale.owner_epoch += 1;
        assert!(!resumes(&stale));
        let mut stale = set.clone();
        stale.spec_id = "spec-2".to_owned();
        assert!(!resumes(&stale));
        let mut stale = set.clone();
        stale.spec_digest = format!("blake3:{}", "0".repeat(64));
        assert!(!resumes(&stale));
        let mut stale = set.clone();
        stale.final_revision = format!("blake3:{}", "0".repeat(64));
        assert!(!resumes(&stale));
        let mut stale = set.clone();
        stale.state = VerifierChallengeSetStateV1::Approved;
        assert!(!resumes(&stale));
    }

    #[test]
    fn verifier_retention_evicts_oldest_terminal_sets_but_never_active_sets() {
        assert!(!prune_terminal_verifier_challenge_sets(
            &mut HashMap::new(),
            0
        ));
        let mut sets = HashMap::from([
            (
                "active".to_owned(),
                challenge_set(
                    VerifierChallengeSetStateV1::AwaitingApproval,
                    1,
                    profile("active-profile", "server_auth:verifier", &"1".repeat(64)),
                ),
            ),
            (
                "old-terminal".to_owned(),
                challenge_set(
                    VerifierChallengeSetStateV1::Aborted,
                    2,
                    profile("old-profile", "server_auth:verifier", &"2".repeat(64)),
                ),
            ),
            (
                "new-terminal".to_owned(),
                challenge_set(
                    VerifierChallengeSetStateV1::Settled,
                    3,
                    profile("new-profile", "server_auth:verifier", &"3".repeat(64)),
                ),
            ),
            (
                "uncertain".to_owned(),
                challenge_set(
                    VerifierChallengeSetStateV1::Unknown,
                    4,
                    profile("uncertain-profile", "server_auth:verifier", &"4".repeat(64)),
                ),
            ),
        ]);

        assert!(prune_terminal_verifier_challenge_sets(&mut sets, 4));
        assert!(!sets.contains_key("old-terminal"));
        assert!(sets.contains_key("new-terminal"));
        assert!(sets.contains_key("uncertain"));
        assert!(sets.contains_key("active"));
        assert!(!prune_terminal_verifier_challenge_sets(&mut sets, 1));
        assert!(sets.contains_key("active"));
        assert!(sets.contains_key("uncertain"));
    }

    #[test]
    fn verifier_retention_never_drops_unknown_outcomes() {
        let mut sets = HashMap::from([
            (
                "unknown".to_owned(),
                challenge_set(
                    VerifierChallengeSetStateV1::Unknown,
                    1,
                    profile("unknown-profile", "server_auth:verifier", &"1".repeat(64)),
                ),
            ),
            (
                "aborted".to_owned(),
                challenge_set(
                    VerifierChallengeSetStateV1::Aborted,
                    2,
                    profile("aborted-profile", "server_auth:verifier", &"2".repeat(64)),
                ),
            ),
            (
                "active".to_owned(),
                challenge_set(
                    VerifierChallengeSetStateV1::AwaitingApproval,
                    3,
                    profile("active-profile", "server_auth:verifier", &"3".repeat(64)),
                ),
            ),
        ]);

        assert!(prune_terminal_verifier_challenge_sets(&mut sets, 3));
        assert!(sets.contains_key("unknown"));
        assert!(!sets.contains_key("aborted"));
        assert!(sets.contains_key("active"));
    }
}

#[cfg(test)]
mod guard_approval_projection_tests {
    use super::*;

    #[test]
    fn terminal_consent_preflight_digest_binds_every_dispatch_input_and_owner_epoch() {
        let base = TerminalConsentPreflightBindingV1 {
            approved_arguments_digest: format!("blake3:{}", "a".repeat(64)),
            profile_digest: format!("blake3:{}", "b".repeat(64)),
            executable_digest: format!("blake3:{}", "c".repeat(64)),
            workspace_root: "/workspace/project".to_owned(),
            workspace_revision: format!("blake3:{}", "d".repeat(64)),
            owner_epoch: 7,
            launch_digest: format!("blake3:{}", "e".repeat(64)),
            guarantee_record: "backend=bubblewrap\nfilesystem_write=enforced".to_owned(),
            direct_permission_mode_digest: None,
            direct_permission_mode_revision: None,
        };
        let digest = terminal_consent_preflight_digest(&base).unwrap();
        assert_eq!(terminal_consent_preflight_digest(&base).unwrap(), digest);

        let mut changed = base.clone();
        changed.owner_epoch += 1;
        assert_ne!(terminal_consent_preflight_digest(&changed).unwrap(), digest);
        let mut changed = base.clone();
        changed.launch_digest = format!("blake3:{}", "f".repeat(64));
        assert_ne!(terminal_consent_preflight_digest(&changed).unwrap(), digest);
        let mut changed = base.clone();
        changed.profile_digest = format!("blake3:{}", "f".repeat(64));
        assert_ne!(terminal_consent_preflight_digest(&changed).unwrap(), digest);
        let mut changed = base.clone();
        changed.workspace_revision = format!("blake3:{}", "f".repeat(64));
        assert_ne!(terminal_consent_preflight_digest(&changed).unwrap(), digest);
        let mut changed = base.clone();
        changed
            .guarantee_record
            .push_str("\nnetwork_egress=unsupported");
        assert_ne!(terminal_consent_preflight_digest(&changed).unwrap(), digest);
        let mut changed = base.clone();
        changed.direct_permission_mode_digest = Some(format!("blake3:{}", "f".repeat(64)));
        changed.direct_permission_mode_revision = Some(1);
        assert_ne!(terminal_consent_preflight_digest(&changed).unwrap(), digest);
        let mut changed = base.clone();
        changed.direct_permission_mode_digest = Some(format!("blake3:{}", "b".repeat(64)));
        changed.direct_permission_mode_revision = Some(2);
        assert_ne!(terminal_consent_preflight_digest(&changed).unwrap(), digest);
    }

    fn write_target() -> Value {
        map_value([
            ("target", Value::String("/workspace/report.txt".to_owned())),
            ("resource", Value::String("report.txt".to_owned())),
            ("operation", Value::String("write".to_owned())),
            ("existed", Value::Bool(true)),
        ])
    }

    #[test]
    fn consent_projection_is_host_derived_bounded_and_deny_only_without_assessment() {
        let targets = Value::Array(vec![write_target()]);
        let mut fields = BTreeMap::new();
        add_guard_consent_projection(
            &mut fields,
            crate::guard::EffectOriginKindV1::SessionBatch,
            crate::guard::FILES_WRITE_ID,
            &targets,
            None,
            Some("ses_projection_test"),
        )
        .unwrap();
        assert_eq!(
            fields.get("origin"),
            Some(&Value::String("session_batch".to_owned()))
        );
        assert_eq!(
            fields.get("source"),
            Some(&Value::String("core.tool_batch".to_owned()))
        );
        assert_eq!(
            fields.get("policyID"),
            Some(&Value::String(
                crate::guard::WORKSPACE_WRITE_POLICY_ID.to_owned()
            ))
        );
        assert_eq!(
            fields.get("normalizedAction"),
            Some(&Value::String(crate::guard::FILES_WRITE_ID.to_owned()))
        );
        assert_eq!(fields.get("allowEnabled"), Some(&Value::Bool(false)));
        assert_eq!(
            fields.get("noResponse"),
            Some(&Value::String("deny_and_expire".to_owned()))
        );
        assert_eq!(
            fields.get("guaranteeAssessment"),
            Some(&map_value([
                ("status", Value::String("not_assessed".to_owned())),
                ("residual", Value::Nil),
            ]))
        );
        let summary = fields
            .get("argumentSummary")
            .expect("safe summary is present");
        assert!(
            matches!(summary, Value::Map(values) if values.get("status") == Some(&Value::String("available".to_owned())) && values.get("text").and_then(|value| match value { Value::String(text) => Some(text.contains("report.txt")), _ => None }) == Some(true))
        );
        assert!(!format!("{fields:?}").contains("secret"));
    }

    #[test]
    fn terminal_command_consent_summary_is_bounded_and_redacts_sensitive_values() {
        let arguments = map_value([
            ("shellProfileID", Value::String("linux.bash".to_owned())),
            (
                "command",
                Value::String(
                    "printf 'hello'; API_TOKEN=abc123 npm test --password 'very secret'; printf Bearer token123".to_owned(),
                ),
            ),
            ("cwd", Value::String("/workspace".to_owned())),
            ("timeoutMs", Value::Unsigned(1000)),
            (
                "resolvedEnvironment",
                map_value([("PRIVATE_KEY", Value::String("must-not-appear".to_owned()))]),
            ),
        ]);
        let targets = Value::Array(vec![map_value([
            ("target", Value::String("/workspace".to_owned())),
            ("resource", Value::String(".".to_owned())),
            ("operation", Value::String("run".to_owned())),
            ("existed", Value::Bool(true)),
        ])]);
        let summary = terminal_command_consent_summary(&arguments, &targets)
            .expect("a bounded redacted command should be available for approval");
        assert!(summary.contains("printf 'hello'"));
        assert!(summary.contains("API_TOKEN=[redacted]"));
        assert!(summary.contains("--password [redacted]"));
        assert!(summary.contains("Bearer [redacted]"));
        assert!(!summary.contains("abc123"));
        assert!(!summary.contains("very secret"));
        assert!(!summary.contains("token123"));
        assert!(!summary.contains("must-not-appear"));
        assert!(summary.len() <= 512);
    }

    #[test]
    fn terminal_command_consent_summary_is_unavailable_for_unrenderable_input() {
        let arguments = map_value([
            ("shellProfileID", Value::String("linux.bash".to_owned())),
            ("command", Value::String("printf 'unterminated".to_owned())),
            ("cwd", Value::String("/workspace".to_owned())),
            ("timeoutMs", Value::Unsigned(1000)),
            ("resolvedEnvironment", map_value([])),
        ]);
        let targets = Value::Array(vec![map_value([
            ("target", Value::String("/workspace".to_owned())),
            ("resource", Value::String(".".to_owned())),
            ("operation", Value::String("run".to_owned())),
            ("existed", Value::Bool(true)),
        ])]);
        assert_eq!(terminal_command_consent_summary(&arguments, &targets), None);
        let mut fields = BTreeMap::new();
        add_guard_consent_projection(
            &mut fields,
            crate::guard::EffectOriginKindV1::UserAction,
            crate::guard::TERMINAL_RUN_ID,
            &targets,
            None,
            Some("ses_terminal_summary_unavailable"),
        )
        .unwrap();
        set_terminal_argument_summary(&mut fields, &arguments, &targets);
        set_guard_guarantee_assessment(&mut fields, &[]).unwrap();
        assert_eq!(fields.get("allowEnabled"), Some(&Value::Bool(false)));
    }

    #[test]
    fn terminal_command_consent_summary_fails_closed_on_credentials_inside_quoted_literals() {
        assert_eq!(
            redact_terminal_command("printf 'Authorization: Bearer literal-secret'"),
            None
        );
    }

    #[test]
    fn consent_projection_rejects_unknown_actions_and_oversized_targets() {
        let targets = Value::Array(vec![write_target()]);
        let mut fields = BTreeMap::new();
        assert!(
            add_guard_consent_projection(
                &mut fields,
                crate::guard::EffectOriginKindV1::SessionBatch,
                "caller.forged.action",
                &targets,
                None,
                None,
            )
            .is_err()
        );
        let oversized = Value::Array((0..65).map(|_| write_target()).collect());
        assert!(
            add_guard_consent_projection(
                &mut fields,
                crate::guard::EffectOriginKindV1::SessionBatch,
                crate::guard::FILES_WRITE_ID,
                &oversized,
                None,
                None,
            )
            .is_err()
        );
    }
}

fn current_unix_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_millis().try_into().unwrap_or(u64::MAX))
        .unwrap_or(u64::MAX)
}

fn response_error(
    request: &RpcRequestV1,
    fence: &FrameFence,
    code: &'static str,
    category: ErrorCategoryV1,
    message: &'static str,
) -> RpcResponseV1 {
    RpcResponseV1 {
        owner_epoch: fence.owner_epoch(),
        process_incarnation: fence.process_incarnation().to_owned(),
        request_id: request.request_id.clone(),
        outcome: RpcOutcomeV1::Error,
        owner_cursor: None,
        receipt_digest: None,
        body: None,
        error: Some(TypedErrorV1 {
            code: code.to_owned(),
            category,
            message: message.to_owned(),
            retry_class: RetryClassV1::Never,
            retry_after_ms: None,
            owner_cursor: None,
            subject_ids: Vec::new(),
            details: None,
        }),
    }
}

/// One-use delivery key for one managed operation. The retained suffix space keeps
/// every derived durable command identifier inside the 256-byte owner-log bound, so
/// a client can never cause a partially applied managed operation through an
/// over-long identifier.
fn tool_batch_arguments_digest(arguments: &Value) -> Result<String, HostError> {
    let encoded = crate::messagepack::encode(arguments, crate::messagepack::FRAME_LIMITS)
        .map_err(|_| invalid())?;
    let mut preimage = b"horizoncode.tool-batch.arguments.v1\0".to_vec();
    preimage.extend_from_slice(&encoded);
    Ok(format!("blake3:{}", blake3::hash(&preimage).to_hex()))
}

fn managed_effect_wave_id(
    effect_batch_id: &str,
    scope: &ManagedAttemptScopeV1,
    wave_index: u8,
) -> String {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"horizoncode.managed-effect-wave-id.v1\0");
    for value in [effect_batch_id, scope.goal_id.as_str(), scope.run_id.as_str(),
        scope.task_id.as_str(), scope.attempt_id.as_str(), scope.session_id.as_str(),
        scope.location_id.as_str()]
    {
        hasher.update(&(value.len() as u64).to_be_bytes());
        hasher.update(value.as_bytes());
    }
    hasher.update(&scope.owner_epoch.to_be_bytes());
    hasher.update(&scope.expected_managed_revision.to_be_bytes());
    hasher.update(&[wave_index]);
    format!("managed_wave_{}", hasher.finalize().to_hex())
}

fn managed_effect_wave_delivery_id(
    request: &RpcRequestV1,
    wave_id: &str,
) -> Result<String, HostError> {
    let base = managed_delivery(request)?;
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"horizoncode.managed-effect-wave-delivery.v1\0");
    for value in [base, wave_id] {
        hasher.update(&(value.len() as u64).to_be_bytes());
        hasher.update(value.as_bytes());
    }
    Ok(format!("managed_wave_delivery_{}", hasher.finalize().to_hex()))
}

/// Deterministic delivery identity for one HostRun binding append. Deriving it
/// from the dispatch-key digest makes an identical replay idempotent while a
/// different payload for the same key fails as a reused delivery.
fn host_run_dispatch_key_digest(
    manifest_digest: &str,
    evaluator_task_id: &str,
    arm_id: &str,
) -> Result<String, ()> {
    if !is_blake3_digest(manifest_digest)
        || evaluator_task_id.is_empty()
        || evaluator_task_id.len() > 256
        || arm_id.is_empty()
        || arm_id.len() > 256
    {
        return Err(());
    }

    // serde_json's default Map is key-sorted; serializing this object therefore
    // matches the evaluator's compact, recursively sorted canonical JSON tuple.
    let canonical = serde_json::to_vec(&serde_json::json!({
        "armId": arm_id,
        "lane": "HUP_PAIRED_HOST_RUN_V1",
        "manifestDigest": manifest_digest,
        "taskId": evaluator_task_id,
    }))
    .map_err(|_| ())?;
    let manifest_task_arm_digest = ring::digest::digest(&ring::digest::SHA256, &canonical);
    let raw_key = format!(
        "sha256:{}",
        manifest_task_arm_digest
            .as_ref()
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>()
    );
    Ok(format!("blake3:{}", blake3::hash(raw_key.as_bytes()).to_hex()))
}

fn host_run_bind_delivery_id(dispatch_key_digest: &str) -> String {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"horizoncode.host-run-bind-delivery.v1\0");
    hasher.update(dispatch_key_digest.as_bytes());
    format!("host_run_bind_{}", hasher.finalize().to_hex())
}

/// Deterministic delivery identity for one P8 post-commit receipt append.
fn host_run_bind_receipt_delivery_id(dispatch_key_digest: &str) -> String {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"horizoncode.host-run-bind-receipt-delivery.v1\0");
    hasher.update(dispatch_key_digest.as_bytes());
    format!("host_run_bind_receipt_{}", hasher.finalize().to_hex())
}

/// A request cursor is only a lookup claim. Return a P8 receipt only after the
/// canonical durable resolver has rebuilt and exactly matched it.
fn resolve_host_run_p8_owner_receipt(
    submitted: &crate::managed_control::HostRunDispatchP8OwnerReceiptV1,
    resolve: impl FnOnce(
        &crate::managed_control::HostRunDispatchP8OwnerReceiptV1,
    ) -> Result<crate::managed_control::HostRunDispatchP8OwnerReceiptV1, HostError>,
) -> Result<crate::managed_control::HostRunDispatchP8OwnerReceiptV1, HostError> {
    let resolved = resolve(submitted)?;
    resolved.validate().map_err(managed_error)?;
    if resolved != *submitted {
        return Err(managed_conflict(
            "HostRun P8 durable resolver returned a different OwnerLog receipt",
        ));
    }
    Ok(resolved)
}

/// Caller claims for one frozen-invocation mint. Every field is cross-checked
/// against a validated evaluator manifest and recomputed; none of them is
/// authority on its own. P8's Python minter produces the same tuple
/// (`host_run_frozen_invocation_candidate`); this Rust seam re-derives it so a
/// caller can never choose the tuple it records.
pub(crate) struct HostRunFrozenInvocationClaimsV1 {
    pub(crate) task_id: String,
    pub(crate) arm_id: String,
    pub(crate) task_group: String,
    pub(crate) manifest_digest: String,
    pub(crate) dispatch_key_digest: String,
}

const EVAL_MANIFEST_SCHEMA: &str = "horizoncode.eval.manifest.v1";
const EVAL_MANIFEST_REQUIRED_KEYS: [&str; 12] = [
    "schema",
    "runId",
    "lane",
    "benchmark",
    "shared",
    "arms",
    "tasks",
    "taskPartitions",
    "analysis",
    "comparison",
    "failurePolicy",
    "exclusionPolicy",
];
const MAX_EVAL_MANIFEST_BYTES: usize = 2 * 1024 * 1024;
const MAX_EVAL_MANIFEST_TASKS: usize = 10_000;
const MAX_EVAL_MANIFEST_ID_BYTES: usize = 128;

fn frozen_invocation_invalid(message: &'static str) -> HostError {
    ("host_run_frozen_invocation_invalid", ErrorCategoryV1::Validation, message)
}

fn frozen_invocation_conflict(message: &'static str) -> HostError {
    ("host_run_frozen_invocation_conflict", ErrorCategoryV1::Conflict, message)
}

/// Frozen ids are bounded ASCII tokens: non-empty, ≤128 bytes, never
/// whitespace or control characters (mirrors P8's `_require_id`).
fn frozen_manifest_token_ok(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= MAX_EVAL_MANIFEST_ID_BYTES
        && !value.chars().any(|c| c.is_control() || c.is_whitespace())
}

/// Canonical-JSON safety: Python's `allow_nan=False` and Rust's digest layout
/// only agree for manifests without floating-point values, so any number that
/// is not an integer is rejected rather than risking a cross-language digest
/// divergence.
fn manifest_contains_float(value: &serde_json::Value) -> bool {
    match value {
        serde_json::Value::Number(number) => number.is_f64(),
        serde_json::Value::Array(items) => items.iter().any(manifest_contains_float),
        serde_json::Value::Object(map) => map.values().any(manifest_contains_float),
        _ => false,
    }
}

/// Mint-and-record the frozen invocation from a **validated** evaluator
/// manifest (P2 item-21 step 1, the upstream half of the bind chain). The
/// derivation is byte-compatible with P8's `host_run_frozen_invocation_candidate`:
///
/// * manifest must carry the frozen v1 schema, required fields and policies;
/// * `manifestDigest` is recomputed as BLAKE3 over compact sorted-key JSON and
///   must equal the claim (§12.23);
/// * `evaluatorTaskId`/`armId` must name exactly one frozen task/arm, and
///   `taskGroup` is taken from the manifest task — never caller-chosen;
/// * `dispatchKeyDigest` must equal `host_run_dispatch_key_digest` over the
///   recomputed manifest digest and frozen pair.
///
/// On any failure nothing is written: the durable store keeps no record for
/// this dispatch key. The caller must have validated the manifest at its
/// authenticated boundary first; this seam re-checks every manifest-dependent
/// claim rather than trusting it. No production caller exists yet — the trigger
/// is an authenticated evaluator-manifest admission path, which is not live.
pub(crate) fn record_frozen_invocation_from_validated_manifest(
    worker_pool: &mut crate::worker_durable::WorkerPoolControl,
    manifest: &serde_json::Value,
    claims: HostRunFrozenInvocationClaimsV1,
) -> Result<crate::worker_durable::HostRunFrozenInvocationV1, HostError> {
    let manifest_object = manifest
        .as_object()
        .ok_or_else(|| frozen_invocation_invalid("evaluator manifest must be an object"))?;
    for key in EVAL_MANIFEST_REQUIRED_KEYS {
        if !manifest_object.contains_key(key) {
            return Err(frozen_invocation_invalid(
                "evaluator manifest lacks a required frozen field",
            ));
        }
    }
    if manifest_object.get("schema").and_then(serde_json::Value::as_str) != Some(EVAL_MANIFEST_SCHEMA) {
        return Err(frozen_invocation_invalid(
            "evaluator manifest schema is not the frozen v1 schema",
        ));
    }
    if manifest_object.get("failurePolicy").and_then(serde_json::Value::as_str)
        != Some("typed_fail_closed_v1")
    {
        return Err(frozen_invocation_invalid(
            "evaluator manifest failurePolicy must stay typed fail-closed",
        ));
    }
    if manifest_object.get("exclusionPolicy").and_then(serde_json::Value::as_str)
        != Some("declared_partition_only_v1")
    {
        return Err(frozen_invocation_invalid(
            "evaluator manifest exclusionPolicy must stay partition-declared",
        ));
    }
    match manifest_object.get("lane").and_then(serde_json::Value::as_str) {
        Some("development" | "smoke" | "heldout") => {}
        _ => return Err(frozen_invocation_invalid("evaluator manifest lane is not frozen")),
    }
    let canonical = serde_json::to_string(manifest)
        .map_err(|_| frozen_invocation_invalid("evaluator manifest is not canonical JSON"))?;
    if canonical.len() > MAX_EVAL_MANIFEST_BYTES {
        return Err(frozen_invocation_invalid(
            "evaluator manifest exceeds the canonical byte limit",
        ));
    }
    if manifest_contains_float(manifest) {
        return Err(frozen_invocation_invalid(
            "evaluator manifest must not contain floating-point values",
        ));
    }
    for value in [&claims.task_id, &claims.arm_id, &claims.task_group] {
        if !frozen_manifest_token_ok(value) {
            return Err(frozen_invocation_invalid(
                "frozen invocation id claim is invalid",
            ));
        }
    }
    if !is_blake3_digest(&claims.manifest_digest) || !is_blake3_digest(&claims.dispatch_key_digest) {
        return Err(frozen_invocation_invalid(
            "frozen invocation digest claim is not a canonical blake3 digest",
        ));
    }
    let tasks = manifest_object
        .get("tasks")
        .and_then(serde_json::Value::as_array)
        .filter(|tasks| !tasks.is_empty() && tasks.len() <= MAX_EVAL_MANIFEST_TASKS)
        .ok_or_else(|| frozen_invocation_invalid("evaluator manifest has no frozen tasks"))?;
    for task in tasks {
        let task_id = task
            .get("taskId")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| frozen_invocation_invalid("frozen task lacks a taskId"))?;
        let task_group = task
            .get("taskGroup")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| frozen_invocation_invalid("frozen task lacks a taskGroup"))?;
        if !frozen_manifest_token_ok(task_id) || !frozen_manifest_token_ok(task_group) {
            return Err(frozen_invocation_invalid("frozen task id or group is invalid"));
        }
    }
    let arms = manifest_object
        .get("arms")
        .and_then(serde_json::Value::as_array)
        .filter(|arms| !arms.is_empty())
        .ok_or_else(|| frozen_invocation_invalid("evaluator manifest has no frozen arms"))?;
    for arm in arms {
        let arm_id = arm
            .get("id")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| frozen_invocation_invalid("frozen arm lacks an id"))?;
        if !frozen_manifest_token_ok(arm_id) {
            return Err(frozen_invocation_invalid("frozen arm id is invalid"));
        }
    }
    // Cross-checks: from here on, nothing is written if any claim diverges
    // from the validated manifest.
    let matching_tasks: Vec<&serde_json::Value> = tasks
        .iter()
        .filter(|task| task.get("taskId").and_then(serde_json::Value::as_str) == Some(claims.task_id.as_str()))
        .collect();
    if matching_tasks.len() != 1 {
        return Err(frozen_invocation_invalid(
            "frozen task id is not in the evaluator manifest",
        ));
    }
    let manifest_task_group = matching_tasks[0]
        .get("taskGroup")
        .and_then(serde_json::Value::as_str)
        .expect("frozen task taskGroup was validated above");
    if claims.task_group != manifest_task_group {
        return Err(frozen_invocation_conflict(
            "taskGroup differs from the frozen manifest task",
        ));
    }
    if arms
        .iter()
        .filter(|arm| arm.get("id").and_then(serde_json::Value::as_str) == Some(claims.arm_id.as_str()))
        .count()
        != 1
    {
        return Err(frozen_invocation_invalid(
            "arm id is not in the evaluator manifest",
        ));
    }
    let recomputed_manifest_digest =
        format!("blake3:{}", blake3::hash(canonical.as_bytes()).to_hex());
    if recomputed_manifest_digest != claims.manifest_digest {
        return Err(frozen_invocation_conflict(
            "manifest digest does not recompute from the validated manifest",
        ));
    }
    let recomputed_dispatch_key = host_run_dispatch_key_digest(
        &claims.manifest_digest,
        &claims.task_id,
        &claims.arm_id,
    )
    .map_err(|_| frozen_invocation_invalid("frozen pair identity cannot be recomputed"))?;
    if recomputed_dispatch_key != claims.dispatch_key_digest {
        return Err(frozen_invocation_conflict(
            "dispatch key does not equal its recomputed frozen pair identity",
        ));
    }
    let invocation = crate::worker_durable::HostRunFrozenInvocationV1 {
        dispatch_key_digest: recomputed_dispatch_key,
        manifest_digest: recomputed_manifest_digest,
        evaluator_task_id: claims.task_id,
        arm_id: claims.arm_id,
        task_group: manifest_task_group.to_owned(),
    };
    worker_pool
        .record_frozen_invocation(&invocation)
        .map_err(|_| {
            frozen_invocation_conflict("frozen invocation could not be recorded durably")
        })?;
    Ok(invocation)
}

/// ServerAuth gate shared by the HostRun bind/receipt routes: the typed
/// principal must be the authenticated ServerAuth subject behind this exact
/// principal binding.
fn require_host_run_server_auth<'a>(
    authenticated_principal: Option<&'a crate::protocol::AuthenticatedPrincipalV1>,
    principal: &str,
) -> Result<&'a str, HostError> {
    let auth = authenticated_principal.ok_or((
        "missing_principal",
        ErrorCategoryV1::Authorization,
        "HostRun operations require authenticated ServerAuth",
    ))?;
    let subject = match auth {
        crate::protocol::AuthenticatedPrincipalV1::ServerAuth { subject }
            if valid_server_auth_subject(subject) =>
        {
            subject
        }
        _ => {
            return Err((
                "missing_principal",
                ErrorCategoryV1::Authorization,
                "HostRun operations require authenticated ServerAuth",
            ))
        }
    };
    if principal != format!("server_auth:{subject}") {
        return Err((
            "effect_denied",
            ErrorCategoryV1::Authorization,
            "HostRun principal differs from authenticated ServerAuth",
        ));
    }
    Ok(subject)
}

fn managed_delivery(request: &RpcRequestV1) -> Result<&str, HostError> {
    let delivery = request.delivery_id.as_deref().ok_or_else(invalid)?;
    if delivery.is_empty()
        || delivery.len() > MAX_MANAGED_DELIVERY_ID_BYTES
        || !delivery
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || b"._-".contains(&byte))
    {
        return Err(invalid());
    }
    Ok(delivery)
}

/// Stable Task candidate selector derived only from the durable Task ID and
/// both monotonic counters. Admission still requires all live P1/P8 proofs;
/// this identifier alone carries no authority.
fn managed_candidate_attempt_id(task_id: &str, attempt_count: u16, generation: u64) -> String {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"horizoncode.managed-task-attempt-candidate.v1\0");
    hasher.update(&(task_id.len() as u64).to_be_bytes());
    hasher.update(task_id.as_bytes());
    hasher.update(&u64::from(attempt_count).to_be_bytes());
    hasher.update(&generation.to_be_bytes());
    format!("attempt_{}", hasher.finalize().to_hex())
}

/// Core may only derive child Session identity from the Rust scheduler's exact
/// candidate Attempt ID. The mapping is deterministic across retries and keeps
/// the existing `ses_` identifier grammar; it is never model supplied.
fn managed_child_session_id(attempt_id: &str) -> Option<String> {
    let suffix = attempt_id.strip_prefix("attempt_")?;
    if suffix.len() != 64 || !suffix.bytes().all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase()) {
        return None;
    }
    Some(format!("ses_managed_{attempt_id}"))
}

fn managed_no_process_observation_digest(
    attempt_id: &str,
    worker_execution_id: &str,
    pins_digest: &str,
    peer: &AuthenticatedCorePeerFactsV1,
) -> String {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"horizoncode.managed-pre-admission-no-process-observation.v1\0");
    for value in [
        attempt_id,
        worker_execution_id,
        pins_digest,
        peer.process_incarnation.as_str(),
        peer.executable_identity_digest.as_str(),
        "stdio_bindings_absent",
        "stdio_prepared_absent",
        "stdio_process_refs_absent",
    ] {
        hasher.update(&(value.len() as u64).to_be_bytes());
        hasher.update(value.as_bytes());
    }
    hasher.update(&peer.owner_epoch.to_be_bytes());
    hasher.update(&peer.pid.to_be_bytes());
    hasher.update(&peer.start_identity.to_be_bytes());
    hasher.update(&peer.uid.to_be_bytes());
    hasher.update(&peer.gid.to_be_bytes());
    format!("blake3:{}", hasher.finalize().to_hex())
}

/// Maps the durable managed-control error to the boundary's typed categories. The
/// state machine's own static reasons are safe to surface; storage details are not.
fn managed_error(error: ManagedError) -> HostError {
    match error {
        ManagedError::Invalid(message) => (
            "invalid_managed_request",
            ErrorCategoryV1::Validation,
            message,
        ),
        ManagedError::Conflict(message) => ("managed_conflict", ErrorCategoryV1::Conflict, message),
        ManagedError::NotFound(message) => {
            ("managed_not_found", ErrorCategoryV1::NotFound, message)
        }
        ManagedError::Storage(OwnerLogError::OwnerBusy) => (
            "managed_goal_busy",
            ErrorCategoryV1::Conflict,
            "managed Goal is already owned by a live kernel",
        ),
        ManagedError::Storage(_) => (
            "managed_storage_unavailable",
            ErrorCategoryV1::Unavailable,
            "managed Goal storage is unavailable",
        ),
    }
}

fn managed_conflict(message: &'static str) -> HostError {
    ("managed_conflict", ErrorCategoryV1::Conflict, message)
}

fn verifier_unknown_response(
    set: &VerifierChallengeSetV1,
    snapshot: &ManagedSnapshot,
    reason: &str,
) -> Result<Value, HostError> {
    let attempt = snapshot.attempts.get(&set.attempt_id).ok_or(VERIFIER_RECOVERY_REQUIRED)?;
    let task = snapshot.runs.get(&set.run_id)
        .and_then(|run| run.tasks.get(&attempt.task_id))
        .ok_or(VERIFIER_RECOVERY_REQUIRED)?;
    if attempt.run_id != set.run_id
        || task.active_attempt.as_deref().is_some_and(|active| active != set.attempt_id.as_str())
        || task.pending_verification_attempt.as_deref().is_some_and(|pending| pending != set.attempt_id.as_str())
    {
        return Err(VERIFIER_RECOVERY_REQUIRED);
    }
    let mut response = map_value([
        ("status", Value::String("UNKNOWN".to_owned())),
        ("goalID", Value::String(set.goal_id.clone())),
        ("runID", Value::String(set.run_id.clone())),
        ("taskID", Value::String(attempt.task_id.clone())),
        ("attemptID", Value::String(set.attempt_id.clone())),
        (
            "verificationRunID",
            Value::String(set.verification_run_id.clone()),
        ),
        (
            "challengeSetDigest",
            Value::String(set.challenge_set_digest.clone()),
        ),
        ("finalRevision", Value::String(set.final_revision.clone())),
        ("sourceRevision", Value::String(set.final_revision.clone())),
        ("revision", Value::Unsigned(snapshot.revision)),
        ("reason", Value::String(reason.chars().take(128).collect())),
    ]);
    insert_verifier_challenge_set_identity_fields(&mut response, set, &attempt.task_id)?;
    Ok(response)
}

/// HostKernel resolves immutable verifier profiles, obtains reviewer approval for the
/// exact Guard challenge set, executes each verifier through EffectHost and the existing
/// confined stdio supervisor, captures receipt-backed output/artifacts, and commits typed
/// evidence to the live Attempt. Keep the runtime gate closed until integrated positive,
/// denial, stale-revision, cancellation, restart and UNKNOWN-recovery acceptance passes.
const TRUSTED_VERIFIER_ADAPTER_AVAILABLE: bool = false;

const VERIFIER_ADAPTER_MISSING: HostError = (
    "capability_unavailable",
    ErrorCategoryV1::Capability,
    "the trusted guarded verifier path is implemented but remains unavailable until integrated verifier acceptance passes",
);

const VERIFIER_EXECUTION_UNAVAILABLE: HostError = (
    "capability_unavailable",
    ErrorCategoryV1::Capability,
    "the trusted guarded verifier path remains unavailable until integrated execution and recovery acceptance passes",
);

const VERIFIER_DIGEST_ONLY_INGRESS_DISABLED: HostError = (
    "capability_unavailable",
    ErrorCategoryV1::Capability,
    "digest-only verifier ingress is disabled; Task evidence requires typed supervised verifier output",
);

const VERIFIER_RESOLUTION_MISSING: HostError = (
    "capability_unavailable",
    ErrorCategoryV1::Capability,
    "verifier approval resolution remains unavailable until integrated reviewer and Guard acceptance passes",
);

const VERIFIER_EXECUTION_MISSING: HostError = (
    "capability_unavailable",
    ErrorCategoryV1::Capability,
    "the trusted guarded verifier path remains unavailable until integrated execution and recovery acceptance passes",
);

const VERIFIER_JOURNAL_UNAVAILABLE: HostError = (
    "verification_unknown",
    ErrorCategoryV1::Unavailable,
    "managed verifier authority journal is unavailable; dispatch and finalization are blocked",
);

const VERIFIER_RECOVERY_REQUIRED: HostError = (
    "verification_unknown",
    ErrorCategoryV1::Conflict,
    "managed verifier outcome or authority requires exact journal reconciliation; replay is blocked",
);

/// One Task cannot be its own verifier and the local OS-uid operator is the same
/// trust domain as the executor, so only an independently authenticated principal
/// (`server_auth:<subject>`) may submit verification evidence.
fn require_independent_verifier(principal: &str, executor: &str) -> Result<(), HostError> {
    if principal.starts_with("host_os_uid:") {
        return Err((
            "independent_verifier_required",
            ErrorCategoryV1::Authorization,
            "the local OS-uid principal cannot verify its own Attempt",
        ));
    }
    if principal == executor {
        return Err((
            "independent_verifier_required",
            ErrorCategoryV1::Authorization,
            "the Attempt executor cannot verify its own Attempt",
        ));
    }
    Ok(())
}

/// Bounded non-empty plan text such as an objective or criterion description.
fn plan_text<'a>(
    fields: &'a BTreeMap<String, Value>,
    key: &str,
    max_bytes: usize,
) -> Result<&'a str, HostError> {
    let value = text(fields, key)?;
    if value.trim().is_empty() || value.len() > max_bytes {
        return Err(invalid());
    }
    Ok(value)
}

/// Bounded array of non-empty bounded strings (scope, constraints, source digests,
/// dependencies, criterion ids). Every item is validated before any durable write.
fn plan_items(
    fields: &BTreeMap<String, Value>,
    key: &str,
    max_items: usize,
) -> Result<Vec<String>, HostError> {
    let Some(Value::Array(items)) = fields.get(key) else {
        return Err(invalid());
    };
    if items.len() > max_items {
        return Err(invalid());
    }
    let mut values = Vec::with_capacity(items.len());
    for item in items {
        let Value::String(text) = item else {
            return Err(invalid());
        };
        if text.trim().is_empty() || text.len() > MAX_PLAN_ITEM_BYTES || text.contains('\0') {
            return Err(invalid());
        }
        values.push(text.clone());
    }
    Ok(values)
}

/// Parse and validate an exact canonical capability set before opening or mutating
/// OwnerLog state. The managed-control validator owns the registry and ordering
/// rules; this ingress only supplies the bounded field name and preserves its
/// fail-closed error mapping.
fn plan_capability_ids(
    fields: &BTreeMap<String, Value>,
    key: &str,
) -> Result<Vec<String>, HostError> {
    let max_items = match key {
        "capabilityScope" => MAX_SPEC_CAPABILITY_IDS,
        "requiredCapabilities" => MAX_TASK_REQUIRED_CAPABILITIES,
        _ => return Err(invalid()),
    };
    let values = plan_items(fields, key, max_items)?;
    crate::managed_control::validate_canonical_capability_ids(&values).map_err(managed_error)?;
    Ok(values)
}

/// Decode the exact Task-pinned Core profile revision before any OwnerLog
/// mutation. Revisions use canonical decimal strings on this private wire so
/// the same value is lossless in Rust and JavaScript.
fn plan_profile_selection(
    fields: &BTreeMap<String, Value>,
    key: &str,
) -> Result<(String, u64), HostError> {
    let Some(Value::Map(profile)) = fields.get(key) else {
        return Err(invalid());
    };
    if profile.len() != 2
        || profile
            .keys()
            .any(|field| !matches!(field.as_str(), "profileId" | "revision"))
    {
        return Err(invalid());
    }
    let (Some(Value::String(profile_id)), Some(Value::String(revision))) =
        (profile.get("profileId"), profile.get("revision"))
    else {
        return Err(invalid());
    };
    let parsed_revision = revision.parse::<u64>().map_err(|_| invalid())?;
    // The Core schema's Revision is a positive JS-safe integer. Keep the
    // decimal wire spelling canonical and reject values its owner cannot hold.
    if parsed_revision == 0
        || parsed_revision.to_string() != *revision
        || parsed_revision > 9_007_199_254_740_991
        || profile_id.is_empty()
        || profile_id.len() > 256
        || profile_id
            .bytes()
            .any(|byte| byte.is_ascii_whitespace() || byte.is_ascii_control())
    {
        return Err(invalid());
    }
    Ok((profile_id.clone(), parsed_revision))
}

fn profile_revision_ref_value(reference: &crate::agent_profile::ProfileRevisionRefV1) -> Value {
    map_value([
        ("profileId", Value::String(reference.profile_id.clone())),
        ("revision", Value::String(reference.revision.to_string())),
        (
            "definitionDigest",
            Value::String(reference.definition_digest.clone()),
        ),
    ])
}

/// Strictly validates the complete Core-owned profile definition before the
/// canonical digest helper is allowed to mint a typed value. This validator is
/// deliberately called only from authenticated managed admission; the request
/// principal remains connection metadata and is never accepted from this map.
fn validate_agent_profile_definition(
    value: &Value,
) -> Result<crate::agent_profile::AgentProfileDefinitionV2, HostError> {
    const MAX_PROFILE_BYTES: usize = 256 * 1024;
    const MAX_PROFILE_NODES: usize = 16_384;
    const MAX_LIST: usize = 4096;
    let limits = crate::messagepack::Limits {
        max_encoded_bytes: MAX_PROFILE_BYTES,
        max_nodes: MAX_PROFILE_NODES,
        max_depth: 24,
        max_collection_items: MAX_LIST,
        max_scalar_bytes: 64 * 1024,
    };
    crate::messagepack::encoded_len(value, limits).map_err(|_| invalid())?;
    fn json_value(value: &Value, depth: usize) -> Result<(), HostError> {
        if depth > 24 {
            return Err(invalid());
        }
        match value {
            Value::Nil
            | Value::Bool(_)
            | Value::Unsigned(_)
            | Value::Signed(_)
            | Value::String(_) => Ok(()),
            Value::Float(bits) if f64::from_bits(*bits).is_finite() => Ok(()),
            Value::Float(_) | Value::Binary(_) => Err(invalid()),
            Value::Array(values) => values
                .iter()
                .try_for_each(|value| json_value(value, depth + 1)),
            Value::Map(values) => values
                .values()
                .try_for_each(|value| json_value(value, depth + 1)),
        }
    }
    json_value(value, 0)?;

    fn profile_id(value: &Value, max_bytes: usize) -> Result<(), HostError> {
        let Value::String(text) = value else {
            return Err(invalid());
        };
        if text.is_empty()
            || text.len() > max_bytes
            || text.chars().any(|ch| ch.is_whitespace() || ch.is_control())
        {
            return Err(invalid());
        }
        Ok(())
    }
    fn bounded_string(value: &Value, max_bytes: usize, allow_empty: bool) -> Result<(), HostError> {
        let Value::String(text) = value else {
            return Err(invalid());
        };
        if (!allow_empty && text.is_empty()) || text.len() > max_bytes || text.contains('\0') {
            return Err(invalid());
        }
        Ok(())
    }
    fn enum_string(value: &Value, allowed: &[&str]) -> Result<(), HostError> {
        match value {
            Value::String(text) if allowed.contains(&text.as_str()) => Ok(()),
            _ => Err(invalid()),
        }
    }
    fn unsigned(value: &Value, allow_zero: bool) -> Result<(), HostError> {
        match value {
            Value::Unsigned(value)
                if *value <= 9_007_199_254_740_991 && (allow_zero || *value > 0) =>
            {
                Ok(())
            }
            _ => Err(invalid()),
        }
    }
    /// `arch_V1/12-DOMAIN-SCHEMAS.md` line 28: an unsigned 64-bit counter or
    /// budget crossing JSON is a canonical `DecimalU64`
    /// (`wire-primitives-v1`) **string**, never a JSON number. Anything that
    /// is not a base-10 string with no sign, no leading zero (except `"0"`)
    /// and a value inside `0..=18446744073709551615` fails closed;
    /// `positive` enforces the `PositiveDecimalU64` / `> 0` rule.
    fn decimal_u64(value: &Value, positive: bool) -> Result<(), HostError> {
        let Value::String(text) = value else {
            return Err(invalid());
        };
        if text.is_empty()
            || text.len() > 20
            || !text.bytes().all(|byte| byte.is_ascii_digit())
            || (text.len() > 1 && text.starts_with('0'))
        {
            return Err(invalid());
        }
        let Ok(parsed) = text.parse::<u64>() else {
            return Err(invalid());
        };
        if parsed.to_string() != *text || (positive && parsed == 0) {
            return Err(invalid());
        }
        Ok(())
    }
    fn boolean(value: &Value) -> Result<(), HostError> {
        if matches!(value, Value::Bool(_)) {
            Ok(())
        } else {
            Err(invalid())
        }
    }
    fn array<'a>(value: &'a Value, max: usize) -> Result<&'a [Value], HostError> {
        match value {
            Value::Array(values) if values.len() <= max => Ok(values),
            _ => Err(invalid()),
        }
    }
    fn fields<'a>(
        value: &'a Value,
        required: &[&str],
        optional: &[&str],
    ) -> Result<&'a BTreeMap<String, Value>, HostError> {
        strict_fields(value, required, optional)
    }
    fn artifact(value: &Value) -> Result<(), HostError> {
        let fields = fields(
            value,
            &[
                "artifactId",
                "digest",
                "byteLength",
                "mediaType",
                "classification",
            ],
            &[],
        )?;
        profile_id(fields.get("artifactId").ok_or_else(invalid)?, 256)?;
        let Value::String(digest) = fields.get("digest").ok_or_else(invalid)? else {
            return Err(invalid());
        };
        if !valid_blake3_digest(digest) {
            return Err(invalid());
        }
        let Value::String(length) = fields.get("byteLength").ok_or_else(invalid)? else {
            return Err(invalid());
        };
        if length.is_empty()
            || length.len() > 20
            || (length.len() > 1 && length.starts_with('0'))
            || length.parse::<u64>().is_err()
        {
            return Err(invalid());
        }
        profile_id(fields.get("mediaType").ok_or_else(invalid)?, 256)?;
        enum_string(
            fields.get("classification").ok_or_else(invalid)?,
            &["public", "workspace", "sensitive"],
        )
    }
    fn string_array(
        value: &Value,
        max: usize,
        max_string: usize,
        unique: bool,
    ) -> Result<(), HostError> {
        let mut seen = HashSet::new();
        for item in array(value, max)? {
            profile_id(item, max_string)?;
            let Value::String(item) = item else {
                unreachable!("profile_id validated string")
            };
            if unique && !seen.insert(item) {
                return Err(invalid());
            }
        }
        Ok(())
    }
    fn validate_variant(value: &Value) -> Result<(), HostError> {
        let f = fields(
            value,
            &["match"],
            &[
                "instructionPatchRef",
                "requestOverrides",
                "toolExposureProfile",
                "effort",
            ],
        )?;
        let m = fields(
            f.get("match").ok_or_else(invalid)?,
            &[],
            &["providerId", "modelPattern", "protocol"],
        )?;
        if let Some(value) = m.get("providerId") {
            profile_id(value, 256)?;
        }
        if let Some(value) = m.get("modelPattern") {
            bounded_string(value, 65_536, true)?;
        }
        if let Some(value) = m.get("protocol") {
            enum_string(
                value,
                &[
                    "responses",
                    "chat_completions",
                    "anthropic_messages",
                    "custom",
                ],
            )?;
        }
        if let Some(value) = f.get("instructionPatchRef") {
            artifact(value)?;
        }
        if let Some(value) = f.get("requestOverrides") {
            if !matches!(value, Value::Map(_)) {
                return Err(invalid());
            }
        }
        if let Some(value) = f.get("toolExposureProfile") {
            profile_id(value, 256)?;
        }
        if let Some(value) = f.get("effort") {
            bounded_string(value, 65_536, true)?;
        }
        Ok(())
    }

    let f = fields(
        value,
        &[
            "schemaVersion",
            "profileId",
            "revision",
            "name",
            "description",
            "source",
            "roles",
            "purpose",
            "whenToUse",
            "whenNotToUse",
            "adapter",
            "model",
            "harness",
            "reasoning",
            "variants",
            "instructions",
            "tools",
            "allowedSkillIds",
            "deniedSkillIds",
            "allowedMcpServers",
            "allowedMcpToolPatterns",
            "allowedSubagentIds",
            "deniedSubagentIds",
            "pathRules",
            "context",
            "inputMode",
            "memoryPolicy",
            "isolation",
            "lifecycleHooks",
            "capabilityCeiling",
            "limits",
            "maxParallelChildren",
            "enabled",
        ],
        &[],
    )?;
    if f.get("schemaVersion") != Some(&Value::Unsigned(2)) {
        return Err(invalid());
    }
    profile_id(f.get("profileId").ok_or_else(invalid)?, 256)?;
    decimal_u64(f.get("revision").ok_or_else(invalid)?, true)?;
    bounded_string(f.get("name").ok_or_else(invalid)?, 512, false)?;
    bounded_string(f.get("description").ok_or_else(invalid)?, 65_536, true)?;
    enum_string(f.get("source").ok_or_else(invalid)?, &["builtin", "user"])?;
    let roles = array(f.get("roles").ok_or_else(invalid)?, MAX_LIST)?;
    if roles.is_empty() {
        return Err(invalid());
    }
    let mut unique_roles = HashSet::new();
    for role in roles {
        enum_string(role, &["main", "subagent"])?;
        let Value::String(role) = role else {
            unreachable!("enum validated role string")
        };
        if !unique_roles.insert(role) {
            return Err(invalid());
        }
    }
    for key in ["purpose", "whenToUse", "whenNotToUse"] {
        bounded_string(f.get(key).ok_or_else(invalid)?, 65_536, true)?;
    }

    let adapter = fields(
        f.get("adapter").ok_or_else(invalid)?,
        &["kind", "adapterId"],
        &[],
    )?;
    enum_string(
        adapter.get("kind").ok_or_else(invalid)?,
        &["native", "acp", "cli", "container", "remote"],
    )?;
    profile_id(adapter.get("adapterId").ok_or_else(invalid)?, 256)?;
    let model = fields(
        f.get("model").ok_or_else(invalid)?,
        &["providerId", "modelId"],
        &["reasoningEffort"],
    )?;
    profile_id(model.get("providerId").ok_or_else(invalid)?, 256)?;
    profile_id(model.get("modelId").ok_or_else(invalid)?, 256)?;
    if let Some(value) = model.get("reasoningEffort") {
        bounded_string(value, 65_536, true)?;
    }
    profile_id(f.get("harness").ok_or_else(invalid)?, 256)?;
    bounded_string(f.get("reasoning").ok_or_else(invalid)?, 65_536, true)?;
    for variant in array(f.get("variants").ok_or_else(invalid)?, MAX_LIST)? {
        validate_variant(variant)?;
    }

    let instructions = fields(
        f.get("instructions").ok_or_else(invalid)?,
        &["extraRefs", "maxCompiledTokens"],
        &["baseRef"],
    )?;
    if let Some(value) = instructions.get("baseRef") {
        artifact(value)?;
    }
    for item in array(instructions.get("extraRefs").ok_or_else(invalid)?, MAX_LIST)? {
        artifact(item)?;
    }
    decimal_u64(
        instructions.get("maxCompiledTokens").ok_or_else(invalid)?,
        true,
    )?;
    for tool in array(f.get("tools").ok_or_else(invalid)?, MAX_LIST)? {
        let rule = fields(tool, &["effect", "toolPattern"], &["resourcePattern"])?;
        enum_string(
            rule.get("effect").ok_or_else(invalid)?,
            &["allow", "ask", "deny"],
        )?;
        profile_id(rule.get("toolPattern").ok_or_else(invalid)?, 256)?;
        if let Some(value) = rule.get("resourcePattern") {
            bounded_string(value, 65_536, true)?;
        }
    }
    for key in [
        "allowedSkillIds",
        "deniedSkillIds",
        "allowedMcpServers",
        "allowedMcpToolPatterns",
        "allowedSubagentIds",
        "deniedSubagentIds",
    ] {
        string_array(f.get(key).ok_or_else(invalid)?, MAX_LIST, 256, true)?;
    }
    for rule in array(f.get("pathRules").ok_or_else(invalid)?, MAX_LIST)? {
        let rule = fields(rule, &["effect", "operation", "glob"], &[])?;
        enum_string(
            rule.get("effect").ok_or_else(invalid)?,
            &["allow", "ask", "deny"],
        )?;
        enum_string(
            rule.get("operation").ok_or_else(invalid)?,
            &["read", "write", "execute", "watch"],
        )?;
        bounded_string(rule.get("glob").ok_or_else(invalid)?, 65_536, false)?;
    }

    let context = fields(
        f.get("context").ok_or_else(invalid)?,
        &[
            "isolation",
            "allowImages",
            "allowDocuments",
            "allowArtifacts",
        ],
        &["maxParentHistoryTokens"],
    )?;
    enum_string(
        context.get("isolation").ok_or_else(invalid)?,
        &["fresh", "conversation_slice", "fork"],
    )?;
    for key in ["allowImages", "allowDocuments", "allowArtifacts"] {
        boolean(context.get(key).ok_or_else(invalid)?)?;
    }
    if let Some(value) = context.get("maxParentHistoryTokens") {
        decimal_u64(value, true)?;
    }
    enum_string(
        f.get("inputMode").ok_or_else(invalid)?,
        &["default", "read_only", "careful", "sandbox_auto"],
    )?;
    enum_string(
        f.get("memoryPolicy").ok_or_else(invalid)?,
        &["none", "project_read", "profile_read", "reviewed_write"],
    )?;
    enum_string(
        f.get("isolation").ok_or_else(invalid)?,
        &["read_only", "workspace", "worktree", "external"],
    )?;
    for hook in array(f.get("lifecycleHooks").ok_or_else(invalid)?, MAX_LIST)? {
        let hook = fields(
            hook,
            &[
                "hookId",
                "event",
                "required",
                "mode",
                "timeoutMs",
                "maxOutputBytes",
            ],
            &["matcher"],
        )?;
        profile_id(hook.get("hookId").ok_or_else(invalid)?, 256)?;
        profile_id(hook.get("event").ok_or_else(invalid)?, 256)?;
        boolean(hook.get("required").ok_or_else(invalid)?)?;
        enum_string(
            hook.get("mode").ok_or_else(invalid)?,
            &["blocking", "advisory", "async"],
        )?;
        unsigned(hook.get("timeoutMs").ok_or_else(invalid)?, true)?;
        unsigned(hook.get("maxOutputBytes").ok_or_else(invalid)?, true)?;
        if let Some(value) = hook.get("matcher") {
            {
                let matcher = fields(value, &[], &["toolPattern", "pathGlob", "agentPattern"])?;
                for key in ["toolPattern", "pathGlob", "agentPattern"] {
                    if let Some(value) = matcher.get(key) {
                        bounded_string(value, 65_536, true)?;
                    }
                }
            }
        }
    }
    let capability_value = f.get("capabilityCeiling").ok_or_else(invalid)?;
    string_array(capability_value, 64, 128, true)?;
    let Value::Array(capability_values) = capability_value else {
        unreachable!()
    };
    let capabilities = capability_values
        .iter()
        .map(|value| match value {
            Value::String(value) => value.clone(),
            _ => unreachable!("string_array already validated capability values"),
        })
        .collect::<Vec<_>>();
    if capabilities.windows(2).any(|pair| pair[0] >= pair[1]) {
        return Err(invalid());
    }
    crate::managed_control::validate_canonical_capability_ids(&capabilities)
        .map_err(managed_error)?;
    let limits = fields(
        f.get("limits").ok_or_else(invalid)?,
        &[
            "maxDepth",
            "maxActiveChildren",
            "maxTotalChildren",
            "maxPendingMessages",
            "maxMessageBytes",
        ],
        &["tokenBudget", "wallTimeMs"],
    )?;
    for key in [
        "maxDepth",
        "maxActiveChildren",
        "maxTotalChildren",
        "maxPendingMessages",
        "maxMessageBytes",
    ] {
        unsigned(limits.get(key).ok_or_else(invalid)?, true)?;
    }
    for key in ["tokenBudget", "wallTimeMs"] {
        if let Some(value) = limits.get(key) {
            decimal_u64(value, true)?;
        }
    }
    let max_parallel_children = f.get("maxParallelChildren").ok_or_else(invalid)?;
    unsigned(max_parallel_children, true)?;
    let max_active_children = limits.get("maxActiveChildren").ok_or_else(invalid)?;
    let (Value::Unsigned(max_parallel_children), Value::Unsigned(max_active_children)) =
        (max_parallel_children, max_active_children)
    else {
        unreachable!("validated profile limits must be unsigned")
    };
    if max_parallel_children > max_active_children {
        return Err(invalid());
    }
    boolean(f.get("enabled").ok_or_else(invalid)?)?;

    crate::agent_profile::AgentProfileDefinitionV2::from_host_validated_value(value)
        .ok_or_else(invalid)
}

fn valid_blake3_digest(value: &str) -> bool {
    value.strip_prefix("blake3:").is_some_and(|digest| {
        digest.len() == 64
            && digest
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
    })
}

/// Stable reconciliation marker for a direct-message operation whose durable
/// HostKernel journal is not available. It is intentionally not an inbox receipt:
/// callers must preserve UNKNOWN and may not treat it as proof of append.
fn direct_message_unknown_digest(pins_digest: &str) -> String {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"horizoncode.direct-message-unknown.v1\0");
    hasher.update(pins_digest.as_bytes());
    format!("blake3:{}", hasher.finalize().to_hex())
}

/// Managed message reconciliation has a separate domain and lane identity.
/// This is not an inbox receipt: `UNKNOWN` never authorizes a Core append or wake.
fn managed_message_unknown_digest(pins_digest: &str) -> String {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"horizoncode.managed-message-unknown.v1\0");
    hasher.update(pins_digest.as_bytes());
    format!("blake3:{}", hasher.finalize().to_hex())
}

fn managed_message_unknown_response(
    pins: &crate::protocol::ManagedMessageAuthorityPinsV1,
    pins_digest: &str,
) -> Value {
    map_value([
        ("status", Value::String("UNKNOWN".to_owned())),
        ("messageID", Value::String(pins.message_id.clone())),
        ("parentSessionID", Value::String(pins.parent_session_id.clone())),
        ("childSessionID", Value::String(pins.child_session_id.clone())),
        ("deliveryMode", Value::String(pins.delivery_mode.name().to_owned())),
        ("mailboxSequence", Value::String(pins.mailbox_sequence.to_string())),
        ("receiptDigest", Value::String(managed_message_unknown_digest(pins_digest))),
    ])
}

fn direct_message_unknown_response(
    pins: &crate::protocol::DirectMessageAuthorityPinsV1,
    pins_digest: &str,
) -> Value {
    map_value([
        ("status", Value::String("UNKNOWN".to_owned())),
        ("messageID", Value::String(pins.message_id.clone())),
        ("parentSessionID", Value::String(pins.parent_session_id.clone())),
        ("childSessionID", Value::String(pins.child_session_id.clone())),
        ("deliveryMode", Value::String(pins.delivery_mode.name().to_owned())),
        ("mailboxSequence", Value::String(pins.mailbox_sequence.to_string())),
        ("receiptDigest", Value::String(direct_message_unknown_digest(pins_digest))),
    ])
}

fn direct_message_denied_response(reason_code: &str, pins_digest: &str) -> Value {
    map_value([
        ("status", Value::String("DENIED".to_owned())),
        ("reasonCode", Value::String(reason_code.to_owned())),
        ("pinsDigest", Value::String(pins_digest.to_owned())),
    ])
}

fn direct_message_needs_approval_response(
    challenge_id: &str,
    effect_id: &str,
    input_digest: &str,
    expires_at_unix_ms: u64,
    location_id: &str,
) -> Value {
    map_value([
        ("status", Value::String("NEEDS_APPROVAL".to_owned())),
        ("challengeID", Value::String(challenge_id.to_owned())),
        ("effectID", Value::String(effect_id.to_owned())),
        ("capabilityID", Value::String(crate::guard::AGENTS_MESSAGE_ID.to_owned())),
        ("locationID", Value::String(location_id.to_owned())),
        ("inputDigest", Value::String(input_digest.to_owned())),
        ("expiresAtUnixMs", Value::Unsigned(expires_at_unix_ms)),
        ("argumentSummary", map_value([
            ("status", Value::String("available".to_owned())),
            ("text", Value::String("Send a bounded message to the authenticated child session".to_owned())),
        ])),
        ("policySummary", Value::String("agents.message requires explicit approval for this child Attempt".to_owned())),
    ])
}

fn direct_message_settled_response(
    pins: &crate::protocol::DirectMessageAuthorityPinsV1,
    receipt_digest: String,
) -> Value {
    map_value([
        ("status", Value::String(match pins.delivery_mode {
            crate::protocol::DirectMessageDeliveryModeV1::Queue => "QUEUED",
            crate::protocol::DirectMessageDeliveryModeV1::FollowUp => "FOLLOW_UP_SCHEDULED",
        }.to_owned())),
        ("messageID", Value::String(pins.message_id.clone())),
        ("parentSessionID", Value::String(pins.parent_session_id.clone())),
        ("childSessionID", Value::String(pins.child_session_id.clone())),
        ("deliveryMode", Value::String(pins.delivery_mode.name().to_owned())),
        ("mailboxSequence", Value::String(pins.mailbox_sequence.to_string())),
        ("receiptDigest", Value::String(receipt_digest)),
    ])
}

/// Validates the bounded, transcript-free Core selection projection. Context
/// source contents and caller-provided selection digests are never accepted.
fn validate_context_selection(
    value: &Value,
) -> Result<crate::context_selection::ContextSelectionV1, HostError> {
    const MAX_SELECTION_BYTES: usize = 64 * 1024;
    const MAX_SELECTION_NODES: usize = 2048;
    let limits = crate::messagepack::Limits {
        max_encoded_bytes: MAX_SELECTION_BYTES,
        max_nodes: MAX_SELECTION_NODES,
        max_depth: 8,
        max_collection_items: 64,
        max_scalar_bytes: 256,
    };
    crate::messagepack::encoded_len(value, limits).map_err(|_| invalid())?;
    crate::context_selection::ContextSelectionV1::decode(value).ok_or_else(invalid)
}

struct ManagedProviderRouteProjectionV1 {
    provider_id: String,
    model_id: String,
    harness_id: String,
    route_id: String,
    endpoint_revision: String,
    credential_lease_ref: Option<String>,
}

struct ManagedProviderRequestPinsV1 {
    request_id: String,
    request_sequence: u64,
    context_selection_digest: String,
    request_digest: String,
    transport_request_digest: String,
    operation_digest: String,
}

fn managed_provider_route_projection(value: &Value) -> Result<ManagedProviderRouteProjectionV1, HostError> {
    let fields = strict_fields(value,
        &["providerID", "modelID", "harnessID", "routeID", "endpointRevision", "credentialLeaseRef"], &[])?;
    let route = ManagedProviderRouteProjectionV1 {
        provider_id: text(fields, "providerID")?.to_owned(),
        model_id: text(fields, "modelID")?.to_owned(),
        harness_id: text(fields, "harnessID")?.to_owned(),
        route_id: text(fields, "routeID")?.to_owned(),
        endpoint_revision: text(fields, "endpointRevision")?.to_owned(),
        credential_lease_ref: optional_text_field(fields, "credentialLeaseRef")?.map(str::to_owned),
    };
    for id in [&route.provider_id, &route.model_id, &route.harness_id, &route.route_id] {
        validate_effect_identifier(id)?;
    }
    if let Some(credential_lease_ref) = &route.credential_lease_ref {
        validate_effect_identifier(credential_lease_ref)?;
    }
    require_blake3_digest(&route.endpoint_revision)?;
    Ok(route)
}

fn managed_provider_request_pins(value: &Value) -> Result<ManagedProviderRequestPinsV1, HostError> {
    let fields = strict_fields(value,
        &["requestID", "requestSequence", "contextSelectionDigest", "requestDigest", "transportRequestDigest", "operationDigest"], &[])?;
    let request_id = text(fields, "requestID")?.to_owned();
    validate_effect_identifier(&request_id)?;
    let request_sequence = canonical_decimal_revision(fields, "requestSequence")?;
    if !(1..=1024).contains(&request_sequence) { return Err(invalid()); }
    let context_selection_digest = text(fields, "contextSelectionDigest")?.to_owned();
    let request_digest = text(fields, "requestDigest")?.to_owned();
    let transport_request_digest = text(fields, "transportRequestDigest")?.to_owned();
    let operation_digest = text(fields, "operationDigest")?.to_owned();
    require_blake3_digest(&context_selection_digest)?;
    require_blake3_digest(&request_digest)?;
    require_blake3_digest(&transport_request_digest)?;
    if !crate::guard::is_sha256_digest(&operation_digest) {
        return Err(invalid());
    }
    Ok(ManagedProviderRequestPinsV1 { request_id, request_sequence, context_selection_digest, request_digest, transport_request_digest, operation_digest })
}

/// Stable, bounded HostKernel-owned IDs for the Guard records associated with
/// one provider request. They are derived from immutable Attempt sequence pins,
/// never selected by Core or the model.
fn managed_provider_sub_id(kind: &str, attempt_id: &str, request_sequence: u64) -> String {
    let mut bytes = b"horizoncode.managed-provider-sub-id.v1\0".to_vec();
    for part in [kind.as_bytes(), attempt_id.as_bytes()] {
        bytes.extend_from_slice(&(part.len() as u64).to_be_bytes());
        bytes.extend_from_slice(part);
    }
    bytes.extend_from_slice(&request_sequence.to_be_bytes());
    format!("mpr_{}_{}", kind, &blake3::hash(&bytes).to_hex()[..32])
}

fn require_blake3_digest(value: &str) -> Result<(), HostError> {
    if is_blake3_digest(value) { Ok(()) } else { Err(invalid()) }
}

fn managed_provider_rebuild_prepare_binding(
    host: &mut HostKernel,
    scope: &ManagedAttemptScopeV1,
    route: &ManagedProviderRouteProjectionV1,
    pins: &ManagedProviderRequestPinsV1,
    principal: &str,
    fence: &FrameFence,
    prepared_scope_digest: Option<&str>,
    allow_exhausted_budget: bool,
) -> Result<(crate::http_execution::ManagedProviderPrepareBindingV1, Value, String, String), HostError> {
    let snapshot = host.managed_control(&scope.goal_id)?.snapshot().clone();
    let attempt = snapshot.attempts.get(&scope.attempt_id)
        .ok_or_else(|| managed_conflict("provider Attempt is unavailable"))?;
    let run = snapshot.runs.get(&scope.run_id)
        .ok_or_else(|| managed_conflict("provider Run is unavailable"))?;
    let task = run.tasks.get(&scope.task_id)
        .ok_or_else(|| managed_conflict("provider Task is unavailable"))?;
    let binding = attempt.delegation_binding.as_ref()
        .ok_or_else(|| managed_conflict("provider Attempt binding is unavailable"))?;
    let admitted_route = binding.managed_provider_route.as_ref()
        .ok_or_else(|| managed_conflict("managed Attempt has no immutable provider admission route"))?;
    let location = host.locations.get(&scope.location_id).ok_or((
        "location_not_registered", ErrorCategoryV1::Authorization,
        "provider managed Attempt Location is unavailable"))?;
    if fence.owner_epoch() != scope.owner_epoch
        || workspace_revision_digest(&location.canonical_root)? != scope.workspace_revision
        || task.active_attempt.as_deref() != Some(scope.attempt_id.as_str())
        || binding.provider_id != route.provider_id || binding.model_id != route.model_id
        || admitted_route.provider_id != route.provider_id || admitted_route.model_id != route.model_id
        || admitted_route.harness_id != route.harness_id || admitted_route.route_id != route.route_id
        || admitted_route.endpoint_revision != route.endpoint_revision
        || admitted_route.credential_lease_ref != route.credential_lease_ref
        || binding.profile_id.is_empty() || binding.profile_digest.is_empty()
    {
        return Err(managed_conflict("provider binding does not match live Attempt route or workspace"));
    }
    let batch_id = managed_provider_sub_id("batch", &scope.attempt_id, pins.request_sequence);
    let call_id = managed_provider_sub_id("call", &scope.attempt_id, pins.request_sequence);
    let budget_authority_digest = binding.capability_ceiling_digest.clone();
    require_blake3_digest(&budget_authority_digest)?;
    let max_cost_micros = snapshot.specs.get(&run.spec_id)
        .and_then(|spec| spec.content.budget.max_cost_micros).unwrap_or(0);
    if task.profile_token_budget.is_none_or(|limit| limit == 0)
        || (!allow_exhausted_budget && scope.remaining_tokens == 0) {
        return Err(managed_conflict("provider Attempt has no known remaining token budget"));
    }
    let attempt_scope_digest = match prepared_scope_digest {
        Some(digest) => {
            require_blake3_digest(digest)?;
            digest.to_owned()
        }
        None => EffectAttemptScopeV1::Managed(scope.clone()).digest().map_err(|_| invalid())?,
    };
    let approved_arguments = map_value([
        ("providerID", Value::String(route.provider_id.clone())),
        ("modelID", Value::String(route.model_id.clone())),
        ("harnessID", Value::String(route.harness_id.clone())),
        ("routeID", Value::String(route.route_id.clone())),
        ("endpointRevision", Value::String(route.endpoint_revision.clone())),
        ("requestID", Value::String(pins.request_id.clone())),
        ("requestSequence", Value::String(pins.request_sequence.to_string())),
        ("contextSelectionDigest", Value::String(pins.context_selection_digest.clone())),
        ("requestDigest", Value::String(pins.request_digest.clone())),
        ("transportRequestDigest", Value::String(pins.transport_request_digest.clone())),
        ("operationDigest", Value::String(pins.operation_digest.clone())),
        ("maxTokens", Value::String(scope.remaining_tokens.to_string())),
        ("maxCostMicros", Value::String(max_cost_micros.to_string())),
    ]);
    let prepare = crate::http_execution::ManagedProviderPrepareBindingV1 {
        attempt_id: scope.attempt_id.clone(), managed_attempt_digest: attempt_scope_digest,
        owner_epoch: scope.owner_epoch, provider_request_id: format!("mpr_{}_{}", scope.attempt_id, pins.request_sequence),
        request_id: pins.request_id.clone(), request_sequence: pins.request_sequence,
        context_selection_digest: pins.context_selection_digest.clone(), request_digest: pins.request_digest.clone(),
        operation_digest: pins.operation_digest.clone(), transport_request_digest: pins.transport_request_digest.clone(),
        provider_id: route.provider_id.clone(), model_id: route.model_id.clone(), harness_id: route.harness_id.clone(),
        route_id: route.route_id.clone(), endpoint_revision: route.endpoint_revision.clone(),
        credential_ref: route.credential_lease_ref.clone(), permission_scope_digest: scope.permission_scope_digest.clone(),
        principal: principal.to_owned(), session_id: scope.session_id.clone(), location_id: scope.location_id.clone(),
        batch_id: batch_id.clone(), call_id: call_id.clone(), workspace_revision: scope.workspace_revision.clone(),
        budget_lease_id: binding.budget_lease_id.clone(), budget_authority_digest,
        max_tokens: scope.remaining_tokens, max_cost_micros,
    };
    Ok((prepare, approved_arguments, batch_id, call_id))
}

fn managed_provider_rebuild_effect_binding(
    host: &mut HostKernel,
    scope: &ManagedAttemptScopeV1,
    route: &ManagedProviderRouteProjectionV1,
    pins: &ManagedProviderRequestPinsV1,
    record: &crate::managed_control::ManagedProviderRequestRecordV1,
    principal: &str,
    fence: &FrameFence,
    allow_exhausted_budget: bool,
) -> Result<crate::http_execution::ManagedProviderEffectBindingV1, HostError> {
    let (prepare, _, batch_id, call_id) =
        managed_provider_rebuild_prepare_binding(host, scope, route, pins, principal, fence,
            record.prepared_attempt_scope_digest.as_deref(), allow_exhausted_budget)?;
    if prepare.digest().map_err(|_| invalid())? != record.prepare_digest {
        return Err(managed_conflict("provider recovery binding differs from prepared request"));
    }
    let lease = record.capability_lease_digest.as_deref().ok_or_else(||
        managed_conflict("provider dispatch has no persisted capability lease"))?;
    let auth_pins = crate::http_execution::ManagedProviderAuthorizationPinsV1 {
        attempt_id: scope.attempt_id.clone(), managed_attempt_digest: prepare.managed_attempt_digest.clone(),
        owner_epoch: scope.owner_epoch, provider_request_id: record.provider_request_id.clone(),
        request_id: pins.request_id.clone(), request_sequence: pins.request_sequence,
        context_selection_digest: pins.context_selection_digest.clone(), request_digest: pins.request_digest.clone(),
        operation_digest: pins.operation_digest.clone(), transport_request_digest: pins.transport_request_digest.clone(),
        provider_id: route.provider_id.clone(), model_id: route.model_id.clone(), harness_id: route.harness_id.clone(),
        route_id: route.route_id.clone(), endpoint_revision: route.endpoint_revision.clone(),
        credential_ref: route.credential_lease_ref.clone(), guard_challenge_id: record.guard_challenge_id.clone(),
        capability_lease_digest: lease.to_owned(), permission_scope_digest: scope.permission_scope_digest.clone(),
    };
    let binding = crate::http_execution::ManagedProviderEffectBindingV1 {
        pins: auth_pins, principal: principal.to_owned(), session_id: scope.session_id.clone(),
        location_id: scope.location_id.clone(), batch_id, call_id,
        workspace_revision: scope.workspace_revision.clone(), budget_lease_id: prepare.budget_lease_id.clone(),
        budget_authority_digest: prepare.budget_authority_digest.clone(),
        max_tokens: prepare.max_tokens, max_cost_micros: prepare.max_cost_micros,
    };
    if record.authorization_binding_digest.as_deref() != Some(binding.digest().map_err(|_| invalid())?.as_str()) {
        return Err(managed_conflict("provider recovery authorization binding changed"));
    }
    Ok(binding)
}

fn managed_provider_secret_refs(
    snapshot: &crate::managed_control::ManagedSnapshot,
    scope: &ManagedAttemptScopeV1,
) -> Result<(String, String), HostError> {
    let attempt = snapshot.attempts.get(&scope.attempt_id)
        .ok_or_else(|| managed_conflict("provider SecretBroker profile Attempt is unavailable"))?;
    let run = snapshot.runs.get(&scope.run_id)
        .ok_or_else(|| managed_conflict("provider SecretBroker Run is unavailable"))?;
    if !snapshot.runs.contains_key(&scope.run_id) { return Err(managed_conflict("provider SecretBroker Run identity changed")); }
    let binding = attempt.delegation_binding.as_ref()
        .ok_or_else(|| managed_conflict("provider SecretBroker profile binding is unavailable"))?;
    let profile = map_value([
        ("profileId", Value::String(binding.profile_id.clone())),
        ("revision", Value::Unsigned(binding.profile_revision)),
        ("profileDigest", Value::String(binding.profile_digest.clone())),
    ]);
    let encoded = crate::messagepack::encode(&profile, crate::messagepack::FRAME_LIMITS).map_err(|_| invalid())?;
    let mut profile_preimage = b"horizoncode/agent-profile-ref/v1\0".to_vec();
    profile_preimage.extend_from_slice(&encoded);
    let profile_ref = format!("profile_{}", blake3::hash(&profile_preimage).to_hex());
    Ok((profile_ref, scope.run_id.clone()))
}

fn managed_provider_requester_ref(
    authenticated_principal: Option<&crate::protocol::AuthenticatedPrincipalV1>,
) -> Result<String, HostError> {
    let subject = match authenticated_principal {
        Some(crate::protocol::AuthenticatedPrincipalV1::ServerAuth { subject })
            if valid_server_auth_subject(subject) => subject,
        _ => return Err(("missing_principal", ErrorCategoryV1::Authorization,
            "managed provider SecretBroker context requires authenticated ServerAuth")),
    };
    let mut preimage = b"horizoncode/secret-requester/v1\0".to_vec();
    preimage.extend_from_slice(subject.as_bytes());
    Ok(format!("principal_{}", blake3::hash(&preimage).to_hex()))
}

fn provider_begin_replay_response(
    scope: &ManagedAttemptScopeV1,
    route: &ManagedProviderRouteProjectionV1,
    pins: &ManagedProviderRequestPinsV1,
    record: &crate::managed_control::ManagedProviderRequestRecordV1,
) -> Value {
    map_value([
        ("status", Value::String("REPLAY".to_owned())),
        ("providerRequestID", Value::String(record.provider_request_id.clone())),
        ("prepareDigest", Value::String(record.prepare_digest.clone())),
        ("dispatchDigest", record.dispatch_digest.clone().map(Value::String).unwrap_or(Value::Nil)),
        ("sendAuthorization", Value::Nil),
        ("guardChallengeID", Value::String(record.guard_challenge_id.clone())),
        ("effectID", Value::String(record.guard_effect_id.clone())),
        ("capabilityLeaseDigest", record.capability_lease_digest.clone().map(Value::String).unwrap_or(Value::Nil)),
        ("authorizationBindingDigest", record.authorization_binding_digest.clone().map(Value::String).unwrap_or(Value::Nil)),
        ("requestID", Value::String(pins.request_id.clone())),
        ("requestSequence", Value::String(pins.request_sequence.to_string())),
        ("contextSelectionDigest", Value::String(pins.context_selection_digest.clone())),
        ("providerID", Value::String(route.provider_id.clone())),
        ("modelID", Value::String(route.model_id.clone())),
        ("harnessID", Value::String(route.harness_id.clone())),
        ("routeID", Value::String(route.route_id.clone())),
        ("endpointRevision", Value::String(route.endpoint_revision.clone())),
        ("credentialLeaseRef", route.credential_lease_ref.clone().map(Value::String).unwrap_or(Value::Nil)),
        ("requestDigest", Value::String(pins.request_digest.clone())),
        ("transportRequestDigest", Value::String(pins.transport_request_digest.clone())),
        ("operationDigest", Value::String(pins.operation_digest.clone())),
        ("revision", Value::String(scope.expected_managed_revision.to_string())),
        ("managedAttempt", scope.to_value()),
    ])
}

fn managed_pre_admission_idempotency_key(goal_id: &str, run_id: &str, task_id: &str, attempt_id: &str) -> String {
    let mut bytes = b"horizoncode.managed-pre-admission-idempotency.v1\0".to_vec();
    for value in [goal_id, run_id, task_id, attempt_id] {
        bytes.extend_from_slice(&(value.len() as u64).to_be_bytes());
        bytes.extend_from_slice(value.as_bytes());
    }
    format!("managed-pre-admission-v1-{}", blake3::hash(&bytes).to_hex())
}

fn require_managed_provider_server_auth(
    authenticated_principal: Option<&crate::protocol::AuthenticatedPrincipalV1>,
    principal: &str,
) -> Result<(), HostError> {
    let subject = match authenticated_principal {
        Some(crate::protocol::AuthenticatedPrincipalV1::ServerAuth { subject })
            if valid_server_auth_subject(subject) => subject,
        _ => return Err(("missing_principal", ErrorCategoryV1::Authorization,
            "managed provider request requires authenticated ServerAuth")),
    };
    if principal != format!("server_auth:{subject}") {
        return Err(("effect_denied", ErrorCategoryV1::Authorization,
            "managed provider principal differs from authenticated ServerAuth"));
    }
    Ok(())
}

fn validate_managed_provider_live_scope(
    host: &mut HostKernel,
    scope: &ManagedAttemptScopeV1,
    principal: &str,
    fence: &FrameFence,
) -> Result<(), HostError> {
    let target = scope.worktree_target.as_ref().ok_or_else(|| managed_conflict(
        "managed provider scope lacks the HostKernel-pinned worktree target"))?;
    validate_managed_attempt_scope(host, scope, principal, fence, &target.location_id, None)?;
    if scope.request_id.is_none() || scope.request_sequence.is_none() || scope.context_selection_digest.is_none() {
        return Err(managed_conflict("managed provider scope lacks its request-bound ContextSelection pins"));
    }
    Ok(())
}

fn validate_managed_provider_request_scope(
    host: &mut HostKernel,
    scope: &ManagedAttemptScopeV1,
    profile: &crate::agent_profile::AgentProfileDefinitionV2,
    route: &ManagedProviderRouteProjectionV1,
    pins: &ManagedProviderRequestPinsV1,
    principal: &str,
    fence: &FrameFence,
) -> Result<(), HostError> {
    validate_managed_provider_live_scope(host, scope, principal, fence)?;
    if scope.request_id.as_deref() != Some(pins.request_id.as_str())
        || scope.request_sequence != Some(pins.request_sequence)
        || scope.context_selection_digest.as_deref() != Some(pins.context_selection_digest.as_str())
    { return Err(managed_conflict("provider request pins differ from the live managed Attempt scope")); }
    let snapshot = host.managed_control(&scope.goal_id)?.snapshot().clone();
    let attempt = snapshot.attempts.get(&scope.attempt_id)
        .ok_or_else(|| managed_conflict("managed provider Attempt is unavailable"))?;
    let run = snapshot.runs.get(&scope.run_id)
        .ok_or_else(|| managed_conflict("managed provider Run is unavailable"))?;
    let task = run.tasks.get(&scope.task_id)
        .ok_or_else(|| managed_conflict("managed provider Task is unavailable"))?;
    let task_profile = task.agent_profile_revision.as_ref()
        .ok_or_else(|| managed_conflict("managed provider Task profile pin is unavailable"))?;
    let binding = attempt.delegation_binding.as_ref()
        .ok_or_else(|| managed_conflict("managed provider DelegationBinding is unavailable"))?;
    let profile_digest = profile.definition_digest().map_err(|_| invalid())?;
    if task_profile.profile_id != profile.profile_id || task_profile.revision != profile.revision
        || task_profile.definition_digest != profile_digest
        || binding.profile_id != profile.profile_id || binding.profile_revision != profile.revision
        || binding.profile_digest != profile_digest
    { return Err(managed_conflict("provider profile definition differs from the live Task and Attempt pins")); }
    let selected = profile.selected_provider_model()
        .ok_or_else(|| managed_conflict("pinned AgentProfileV2 has no selected provider/model"))?;
    if route.provider_id != selected.0 || route.model_id != selected.1
        || profile.harness_id().as_deref() != Some(route.harness_id.as_str())
        || binding.provider_id != route.provider_id || binding.model_id != route.model_id
    { return Err(managed_conflict("provider route projection differs from the pinned profile selection")); }
    let admitted_route = binding.managed_provider_route.as_ref()
        .ok_or_else(|| managed_conflict("managed Attempt predates immutable provider route admission and cannot dispatch"))?;
    if admitted_route.provider_id != route.provider_id
        || admitted_route.model_id != route.model_id
        || admitted_route.harness_id != route.harness_id
        || admitted_route.route_id != route.route_id
        || admitted_route.endpoint_revision != route.endpoint_revision
        || admitted_route.credential_lease_ref != route.credential_lease_ref
    { return Err(managed_conflict("provider route differs from the immutable Attempt admission route")); }
    let record = host.managed_control(&scope.goal_id)?
        .managed_context_selection(&scope.attempt_id, pins.request_sequence)
        .ok_or_else(|| managed_conflict("provider request ContextSelection receipt is unavailable"))?;
    if record.request_id != pins.request_id || record.selection_digest != pins.context_selection_digest
        || record.managed_revision != scope.expected_managed_revision
    { return Err(managed_conflict("provider request does not match the durable ContextSelection receipt")); }
    let selection = crate::context_selection::ContextSelectionV1::decode_json(&record.selection)
        .ok_or_else(|| managed_conflict("provider request ContextSelection is malformed"))?;
    if selection.lane != "managed" || selection.attempt_id.as_deref() != Some(scope.attempt_id.as_str()) {
        return Err(managed_conflict("provider request ContextSelection belongs to a different lane or Attempt"));
    }
    let profile_ref = selection.sources.iter().find(|source| source.kind == "agent-profile")
        .ok_or_else(|| managed_conflict("provider ContextSelection lacks its profile source"))?;
    let input_ref = selection.sources.iter().find(|source| source.kind == "provider-input")
        .ok_or_else(|| managed_conflict("provider ContextSelection lacks its normalized input source"))?;
    let toolset_ref = selection.sources.iter().find(|source| source.kind == "tool"
        && source.source_id.starts_with("toolset:"))
        .ok_or_else(|| managed_conflict("provider ContextSelection lacks its pinned toolset generation"))?;
    if profile_ref.source_id != profile.profile_id || profile_ref.source_revision != profile.revision.to_string()
        || profile_ref.content_digest != profile_digest
        || toolset_ref.source_id != format!("toolset:{}", route.harness_id)
        || input_ref.source_id != pins.request_id
        || input_ref.source_revision != pins.request_sequence.to_string()
        || input_ref.content_digest != pins.request_digest
        || selection.digest().map_err(|_| invalid())? != pins.context_selection_digest
    { return Err(managed_conflict("provider request digest differs from the pinned profile or exact ContextSelection input")); }
    Ok(())
}

/// Validate the exact provider request identity against the current managed
/// Attempt and its durable ContextSelection. This checks only identity and
/// binding facts; it does not resolve a route, credential, consent or Guard
/// authorization, so it cannot make provider dispatch available.
fn validate_managed_provider_route_pins(
    host: &mut HostKernel,
    scope: &ManagedAttemptScopeV1,
    route: &ManagedProviderRouteProjectionV1,
    pins: &ManagedProviderRequestPinsV1,
) -> Result<(), HostError> {
    if scope.request_id.as_deref() != Some(pins.request_id.as_str())
        || scope.request_sequence != Some(pins.request_sequence)
        || scope.context_selection_digest.as_deref() != Some(pins.context_selection_digest.as_str())
    {
        return Err(managed_conflict("provider request pins differ from the live managed Attempt scope"));
    }
    let snapshot = host.managed_control(&scope.goal_id)?.snapshot().clone();
    let attempt = snapshot.attempts.get(&scope.attempt_id)
        .ok_or_else(|| managed_conflict("managed provider Attempt is unavailable"))?;
    let run = snapshot.runs.get(&scope.run_id)
        .ok_or_else(|| managed_conflict("managed provider Run is unavailable"))?;
    let task = run.tasks.get(&scope.task_id)
        .ok_or_else(|| managed_conflict("managed provider Task is unavailable"))?;
    let binding = attempt.delegation_binding.as_ref()
        .ok_or_else(|| managed_conflict("managed provider DelegationBinding is unavailable"))?;
    if binding.provider_id != route.provider_id || binding.model_id != route.model_id
        || task.active_attempt.as_deref() != Some(scope.attempt_id.as_str())
    {
        return Err(managed_conflict("provider route differs from the immutable Task/Attempt provider selection"));
    }
    let admitted_route = binding.managed_provider_route.as_ref()
        .ok_or_else(|| managed_conflict("managed Attempt predates immutable provider route admission and cannot dispatch"))?;
    if admitted_route.provider_id != route.provider_id
        || admitted_route.model_id != route.model_id
        || admitted_route.harness_id != route.harness_id
        || admitted_route.route_id != route.route_id
        || admitted_route.endpoint_revision != route.endpoint_revision
        || admitted_route.credential_lease_ref != route.credential_lease_ref
    { return Err(managed_conflict("provider route differs from the immutable Attempt admission route")); }
    let record = host.managed_control(&scope.goal_id)?
        .managed_context_selection(&scope.attempt_id, pins.request_sequence)
        .ok_or_else(|| managed_conflict("provider request ContextSelection receipt is unavailable"))?;
    if record.request_id != pins.request_id || record.selection_digest != pins.context_selection_digest
        || record.managed_revision != scope.expected_managed_revision
    {
        return Err(managed_conflict("provider request does not match the durable ContextSelection receipt"));
    }
    let selection = crate::context_selection::ContextSelectionV1::decode_json(&record.selection)
        .ok_or_else(|| managed_conflict("provider request ContextSelection is malformed"))?;
    if selection.lane != "managed" || selection.attempt_id.as_deref() != Some(scope.attempt_id.as_str()) {
        return Err(managed_conflict("provider request ContextSelection belongs to a different lane or Attempt"));
    }
    let profile_ref = selection.sources.iter().find(|source| source.kind == "agent-profile")
        .ok_or_else(|| managed_conflict("provider ContextSelection lacks its profile source"))?;
    let input_ref = selection.sources.iter().find(|source| source.kind == "provider-input")
        .ok_or_else(|| managed_conflict("provider ContextSelection lacks its normalized input source"))?;
    let toolset_ref = selection.sources.iter().find(|source| source.kind == "tool"
        && source.source_id.starts_with("toolset:"))
        .ok_or_else(|| managed_conflict("provider ContextSelection lacks its pinned toolset generation"))?;
    if profile_ref.source_id != binding.profile_id
        || profile_ref.source_revision != binding.profile_revision.to_string()
        || profile_ref.content_digest != binding.profile_digest
        || toolset_ref.source_id != format!("toolset:{}", route.harness_id)
        || input_ref.source_id != pins.request_id
        || input_ref.source_revision != pins.request_sequence.to_string()
        || input_ref.content_digest != pins.request_digest
        || selection.digest().map_err(|_| invalid())? != pins.context_selection_digest
    {
        return Err(managed_conflict("provider request digest differs from its Task-pinned profile or exact ContextSelection input"));
    }
    Ok(())
}

/// Optional text field: an absent key or explicit `nil` is `None`.
fn optional_text_field<'a>(
    fields: &'a BTreeMap<String, Value>,
    key: &str,
) -> Result<Option<&'a str>, HostError> {
    match fields.get(key) {
        None | Some(Value::Nil) => Ok(None),
        Some(value) => value_text(value).map(Some),
    }
}

/// Optional unsigned field: an absent key or explicit `nil` is `None`.
fn optional_unsigned_field(
    fields: &BTreeMap<String, Value>,
    key: &str,
) -> Result<Option<u64>, HostError> {
    match fields.get(key) {
        None | Some(Value::Nil) => Ok(None),
        Some(Value::Unsigned(value)) => Ok(Some(*value)),
        _ => Err(invalid()),
    }
}

fn plan_criteria(fields: &BTreeMap<String, Value>) -> Result<Vec<AcceptanceCriterion>, HostError> {
    let Some(criteria) = fields.get("criteria") else {
        return Err(invalid());
    };
    let Value::Array(items) = criteria else {
        return Err(invalid());
    };
    if items.is_empty() || items.len() > MAX_SPEC_CRITERIA {
        return Err(invalid());
    }
    let mut parsed = Vec::with_capacity(items.len());
    for item in items {
        let nested = strict_fields(item, &["id", "description"], &[])?;
        parsed.push(AcceptanceCriterion {
            id: text(nested, "id")?.to_owned(),
            description: plan_text(nested, "description", MAX_PLAN_ITEM_BYTES)?.to_owned(),
        });
    }
    Ok(parsed)
}

fn plan_budget(fields: &BTreeMap<String, Value>) -> Result<SpecBudget, HostError> {
    let Some(budget) = fields.get("budget") else {
        return Err(invalid());
    };
    let nested = strict_fields(
        budget,
        &[
            "maxTasks",
            "maxAttemptsPerTask",
            "maxRunDurationMs",
            "maxMemoryBytes",
            "maxDiskBytes",
            "maxWorkers",
            "maxTokens",
            "maxCostMicros",
        ],
        &[],
    )?;
    Ok(SpecBudget {
        max_tasks: u16::try_from(get_unsigned(nested, "maxTasks")?).map_err(|_| invalid())?,
        max_attempts_per_task: u16::try_from(get_unsigned(nested, "maxAttemptsPerTask")?)
            .map_err(|_| invalid())?,
        max_run_duration_ms: get_unsigned(nested, "maxRunDurationMs")?,
        max_memory_bytes: optional_unsigned_field(nested, "maxMemoryBytes")?,
        max_disk_bytes: optional_unsigned_field(nested, "maxDiskBytes")?,
        max_workers: u16::try_from(get_unsigned(nested, "maxWorkers")?).map_err(|_| invalid())?,
        max_tokens: optional_unsigned_field(nested, "maxTokens")?,
        max_cost_micros: optional_unsigned_field(nested, "maxCostMicros")?,
    })
}

/// Wall-clock milliseconds for a plan-ingress fact that requires a timestamp. The
/// managed state machine accepts only the JSON safe-integer range.
fn plan_now_ms() -> Result<u64, HostError> {
    let elapsed = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_err(|_| {
            (
                "managed_storage_unavailable",
                ErrorCategoryV1::Unavailable,
                "system time is unavailable",
            )
        })?;
    let millis: u64 = elapsed.as_millis().try_into().unwrap_or(u64::MAX);
    if millis == 0 || millis > 9_007_199_254_740_991 {
        return Err((
            "managed_storage_unavailable",
            ErrorCategoryV1::Unavailable,
            "system time is outside the supported range",
        ));
    }
    Ok(millis)
}

fn managed_task_state(
    snapshot: &ManagedSnapshot,
    run_id: &str,
    task_id: &str,
) -> Result<(bool, u16), HostError> {
    let run = snapshot
        .runs
        .get(run_id)
        .ok_or_else(|| managed_conflict("Run is unknown"))?;
    let task = run
        .tasks
        .get(task_id)
        .ok_or_else(|| managed_conflict("Task is unknown"))?;
    Ok((task.ready, task.attempt_count))
}

/// Bounded projection of one durable direct Attempt.
fn direct_attempt_response(
    status: &str,
    attempt_id: &str,
    control: &DirectAttemptControl,
) -> Result<Value, HostError> {
    let record: &DirectAttemptRecord = control
        .record()
        .ok_or_else(|| managed_conflict("direct Attempt is unknown"))?;
    Ok(map_value([
        ("status", Value::String(status.to_owned())),
        ("attemptID", Value::String(attempt_id.to_owned())),
        (
            "attemptPhase",
            Value::String(record.phase.name().to_owned()),
        ),
        (
            "parentSessionID",
            Value::String(record.intent.parent_session_id.clone()),
        ),
        (
            "childSessionID",
            Value::String(record.intent.child_session_id.clone()),
        ),
        ("agent", Value::String(record.intent.agent.clone())),
        (
            "scopeDigest",
            Value::String(record.intent.scope_digest.clone()),
        ),
        ("receiptDigest", optional_text(&record.receipt_digest)),
        ("resultDigest", optional_text(&record.result_digest)),
        ("failureCode", optional_text(&record.failure_code)),
        (
            "retryable",
            match record.retryable {
                None => Value::Nil,
                Some(value) => Value::Bool(value),
            },
        ),
        ("revision", Value::Unsigned(control.revision())),
    ]))
}

fn managed_begin_settlement(
    control: &mut ManagedControl,
    revision: u64,
    delivery: &str,
    run_id: &str,
    task_id: &str,
    attempt_id: &str,
) -> Result<(), HostError> {
    control
        .apply(
            revision,
            &format!("{delivery}.begin"),
            ManagedCommand::BeginAttemptSettlement {
                run_id: run_id.to_owned(),
                task_id: task_id.to_owned(),
                attempt_id: attempt_id.to_owned(),
            },
        )
        .map_err(managed_error)
}

fn managed_phases(
    snapshot: &ManagedSnapshot,
    attempt_id: &str,
) -> Result<(AttemptPhase, RunPhase), HostError> {
    let attempt = snapshot.attempts.get(attempt_id).ok_or_else(invalid)?;
    let run = snapshot.runs.get(&attempt.run_id).ok_or_else(invalid)?;
    Ok((attempt.phase, run.phase))
}

fn run_phase_name(phase: RunPhase) -> &'static str {
    match phase {
        RunPhase::Planned => "PLAN_ONLY",
        RunPhase::Running => "RUNNING",
        RunPhase::Paused => "PAUSED",
        RunPhase::Reconciling => "RECONCILING",
        RunPhase::Cancelling => "CANCELLING",
        RunPhase::Cancelled => "CANCELLED",
        RunPhase::Verifying => "VERIFYING",
        RunPhase::Succeeded => "SUCCEEDED",
        RunPhase::NeedsYou => "NEEDS_YOU",
        RunPhase::Failed => "FAILED",
    }
}

fn claimed_worker_dispatch_digest(
    proof: &crate::worker_durable::ClaimedWorkerDispatchProofV1,
) -> String {
    let mut bytes = b"horizoncode.claimed-worker-dispatch-proof-digest.v1\0".to_vec();
    let claim_nonce = proof.claim_nonce();
    for value in [
        proof.attempt_id(), proof.worker_execution_id(), proof.binding_digest(),
        proof.pins_digest(), proof.owner_log_id(), proof.owner_log_sequence(),
        proof.owner_log_event_digest(), claim_nonce.as_str(),
    ] {
        bytes.extend_from_slice(&(value.len() as u64).to_be_bytes());
        bytes.extend_from_slice(value.as_bytes());
    }
    bytes.extend_from_slice(&proof.worker_pool_revision().to_be_bytes());
    format!("blake3:{}", blake3::hash(&bytes).to_hex())
}

fn canonical_managed_handoff_digest(
    fields: &BTreeMap<String, Value>,
) -> Result<String, HostError> {
    let mut bytes = b"horizoncode.managed-dispatch-handoff.v1\0".to_vec();
    // Encode in the versioned schema order (interleaving strings and integers)
    // below; maps and serializer ordering never define this authority digest.
    let order: [(&str, bool); 38] = [
        ("goalID", false), ("runID", false), ("taskID", false), ("parentSessionID", false),
        ("attemptID", false),
        ("handoffID", false), ("workerExecutionID", false), ("ownerEpoch", true),
        ("processIncarnation", false), ("profileID", false), ("profileRevision", true),
        ("profileDigest", false), ("permissionScopeDigest", false),
        ("acceptedSpecDigest", false), ("workspaceRevision", false), ("locationID", false),
        ("sessionID", false), ("contextSelectionDigest", false), ("acceptedScopeDigest", false),
        ("capabilityCeilingDigest", false), ("budgetDimension", false),
        ("budgetAmount", true), ("leaseExpiresAtMs", true), ("expectedManagedRevision", true),
        ("claimOwnerLogID", false), ("claimOwnerLogSequence", true),
        ("claimOwnerLogEventDigest", false), ("workerPoolRevision", true),
        ("claimNonce", false), ("claimedProofDigest", false), ("workspaceLeaseID", false),
        ("budgetLeaseID", false), ("resourceLeaseIDs", false), ("worktreeID", false),
        ("worktreeBaseRevision", false), ("worktreePoolRevision", true),
        ("bindingDigest", false), ("pinsDigest", false),
    ];
    for (name, is_integer) in order {
        let value = fields.get(name).ok_or_else(invalid)?;
        if name == "resourceLeaseIDs" {
            let Value::Array(items) = value else { return Err(invalid()) };
            bytes.extend_from_slice(&(items.len() as u64).to_be_bytes());
            for item in items {
                let Value::String(item) = item else { return Err(invalid()) };
                bytes.extend_from_slice(&(item.len() as u64).to_be_bytes());
                bytes.extend_from_slice(item.as_bytes());
            }
        } else if is_integer {
            let Value::Unsigned(number) = value else { return Err(invalid()) };
            bytes.extend_from_slice(&number.to_be_bytes());
        } else {
            let Value::String(string) = value else { return Err(invalid()) };
            bytes.extend_from_slice(&(string.len() as u64).to_be_bytes());
            bytes.extend_from_slice(string.as_bytes());
        }
    }
    let target = fields.get("worktreeTarget").ok_or_else(invalid)?;
    let Value::Map(target_fields) = target else { return Err(invalid()) };
    if get_text(target_fields, "worktreeID")? != get_text(fields, "worktreeID")?
        || get_text(target_fields, "worktreeBaseRevision")? != get_text(fields, "worktreeBaseRevision")?
        || get_text(target_fields, "worktreePoolRevision")?
            != get_unsigned(fields, "worktreePoolRevision")?.to_string()
        || get_text(target_fields, "locationID")? != get_text(fields, "locationID")?
    {
        return Err(invalid());
    }
    for name in [
        "worktreeID", "worktreeBaseRevision", "worktreePoolRevision", "locationID",
        "workspaceID", "workspaceRef", "canonicalRoot", "workspaceRevision",
    ] {
        let Value::String(value) = target_fields.get(name).ok_or_else(invalid)? else { return Err(invalid()) };
        if name == "worktreePoolRevision" && parse_canonical_u64(value).is_none() {
            return Err(invalid());
        }
        if name == "workspaceRevision" && !is_blake3_digest(value) { return Err(invalid()); }
        bytes.extend_from_slice(&(value.len() as u64).to_be_bytes());
        bytes.extend_from_slice(value.as_bytes());
    }
    Ok(format!("blake3:{}", blake3::hash(&bytes).to_hex()))
}

