fn managed_final_inspect_response(
    receipt: &crate::worktree_lifecycle::GuardedWorktreeReceiptV1,
) -> Value {
    let status = match receipt.status() {
        crate::worktree_lifecycle::WorktreeObservedStatusV1::Clean => "CLEAN",
        crate::worktree_lifecycle::WorktreeObservedStatusV1::DirtyOwned => "DIRTY_OWNED",
        crate::worktree_lifecycle::WorktreeObservedStatusV1::DirtyUnattributed => "DIRTY_UNATTRIBUTED",
        crate::worktree_lifecycle::WorktreeObservedStatusV1::Missing => "MISSING",
        crate::worktree_lifecycle::WorktreeObservedStatusV1::Unknown => "UNKNOWN",
    };
    map_value([
        ("status", Value::String("INSPECTED".to_owned())),
        ("operationID", Value::String(receipt.operation_id().to_owned())),
        ("hostReceiptRef", Value::String(receipt.host_receipt_ref().to_owned())),
        ("workspaceRevision", Value::String(receipt.observed_workspace_revision().to_owned())),
        ("worktreeStatus", Value::String(status.to_owned())),
        ("dirtyEntryCount", Value::String(receipt.dirty_entry_count().to_string())),
        ("dirtyEntriesDigest", Value::String(receipt.dirty_entries_digest().to_owned())),
        ("containsUserOwnedChanges", Value::Bool(receipt.contains_user_owned_changes())),
        ("owned", Value::Bool(receipt.owned())),
        ("noFollow", Value::Bool(receipt.no_follow())),
    ])
}

fn managed_reconciliation_complete_response(
    inspect: &crate::worktree_lifecycle::GuardedWorktreeReceiptV1,
    settlement: &crate::worker_durable::WorkerSettlementReceiptV1,
    disposition: &crate::worker_durable::WorkerWorktreeDispositionReceiptV1,
    goal_id: &str,
    run_id: &str,
    task_id: &str,
) -> Value {
    map_value([
        ("status", Value::String("RECONCILED".to_owned())),
        ("inspect", managed_final_inspect_response(inspect)),
        ("settlement", managed_dispatch_settled_response(settlement, disposition,
            goal_id, run_id, task_id)),
    ])
}

