/// Interpret only the fixed Git `status --porcelain=v1 -z` output. Filenames never
/// leave HostKernel; only count/digest/status are included in the durable receipt.
fn inspect_git_status_output(
    output: &[u8],
    root: &Path,
    process_succeeded: bool,
) -> (crate::worktree_lifecycle::WorktreeObservedStatusV1, u32, String, bool) {
    use crate::worktree_lifecycle::WorktreeObservedStatusV1 as Status;
    if !process_succeeded || (!output.is_empty() && output.last() != Some(&0)) {
        return (Status::Unknown, 0, String::new(), false);
    }
    if output.is_empty() {
        return (Status::Clean, 0, String::new(), true);
    }
    let fields = output.split(|byte| *byte == 0).collect::<Vec<_>>();
    if fields.last().is_none_or(|last| !last.is_empty()) {
        return (Status::Unknown, 0, String::new(), false);
    }
    let mut index = 0usize;
    let mut count = 0u32;
    let mut no_follow = true;
    while index + 1 < fields.len() {
        let entry = fields[index];
        if entry.len() < 4 || entry[2] != b' ' {
            return (Status::Unknown, 0, String::new(), false);
        }
        let path = &entry[3..];
        if !git_status_path_is_no_follow(root, path) {
            no_follow = false;
        }
        count = match count.checked_add(1) {
            Some(count) if count <= 100_000 => count,
            _ => return (Status::Unknown, 0, String::new(), false),
        };
        if entry[0] == b'R' || entry[0] == b'C' || entry[1] == b'R' || entry[1] == b'C' {
            index = index.saturating_add(1);
            if index + 1 >= fields.len() || fields[index].is_empty()
                || !git_status_path_is_no_follow(root, fields[index])
            {
                no_follow = false;
            }
        }
        index = index.saturating_add(1);
    }
    if count == 0 || !no_follow {
        return (Status::Unknown, count, format!("blake3:{}", blake3::hash(output).to_hex()), no_follow);
    }
    (Status::DirtyOwned, count, format!("blake3:{}", blake3::hash(output).to_hex()), true)
}

#[cfg(unix)]
fn git_status_path_is_no_follow(root: &Path, bytes: &[u8]) -> bool {
    use std::os::unix::ffi::OsStringExt;
    let relative = PathBuf::from(OsString::from_vec(bytes.to_vec()));
    if relative.as_os_str().is_empty() || relative.is_absolute() {
        return false;
    }
    let components = relative.components().collect::<Vec<_>>();
    if components.iter().any(|component| !matches!(component, Component::Normal(_))) {
        return false;
    }
    let mut cursor = root.to_path_buf();
    for (position, component) in components.iter().enumerate() {
        cursor.push(component.as_os_str());
        match fs::symlink_metadata(&cursor) {
            Ok(metadata) if position + 1 < components.len() => {
                if metadata.file_type().is_symlink() || !metadata.is_dir() { return false; }
            }
            Ok(_) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound
                && position + 1 == components.len() => return true,
            Err(_) => return false,
        }
    }
    true
}

#[cfg(not(unix))]
fn git_status_path_is_no_follow(_: &Path, _: &[u8]) -> bool { false }

